    "【3】\n【杂技演员】\n【信誉】：9-20\n【职业属性】：教育×2＋敏捷×2\n【本职技能】：攀爬，闪避，跳跃，投掷，侦查，游泳，任意两项其他个人或时代特长。\n【介绍】：\n杂技演员可能是参加各级比赛（甚至奥运会）的业余运动员，也可能是专业的演员，在马戏团、嘉年华、歌舞团之类的地方作为娱乐业从业者工作。",
    "【4】\n【演员-戏剧演员】\n【信誉】：9-40\n【职业属性】：教育×2＋外貌×2\n【本职技能】：技艺（表演），乔装，格斗，历史，两项社交技能（魅惑、话术、恐吓、说服），心理学，任意一项其他个人或时代特长。\n【介绍】：\n在1920年代，虽然全国都有大型剧院，美国的戏剧中心仍然是纽约城。英国的情况与之相近，戏剧的中心在伦敦，其他的剧团则在各郡作巡回演出。巡回剧团乘火车旅行，演出内容既包括新编剧目，也包括莎士比亚和其他人的传统剧目。有些剧团也会花时间去国外采风，通常是去加拿大夏威夷澳大利亚和欧洲大陆。",
    "【5】\n【演员-电影演员】\n【信誉】：20-90\n【职业属性】：教育×2＋外貌×2\n【本职技能】：技艺（表演），乔装，汽车驾驶，两项社交技能（魅惑、话术、恐吓、说服），心理学，任意两项其他个人或时代特长（如骑乘或格斗）。\n【介绍】：\n许多演员有相当深厚的文化素养，认为自己才是“正统”的，倾向于轻视电影业的商业活动。直到 20 世纪后期电影业的地位提高，电影演员的薪酬增加，这种情况才发生改变。电影业和电影明星一直是世界人民关注的焦点。许多明星一夜成名，在媒体的聚光灯下过着光鲜亮丽的生活。",
    "【6】\n【事务所侦探、保安】\n【信誉】：20-45\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：一项社交技能（魅惑、话术、恐吓、说服），格斗（斗殴），射击，法律，图书馆，心理学，潜行，追踪。\n【介绍】：\n世界上有许多著名的侦探机构，其中最著名的是平克顿和伯恩斯调查局（后来合并成一家公司）。这样的公司一般有两类工作人员：安保人员和调查人员。企业或个人雇用安保人员来保护自己的资产和人员免受盗贼刺客和绑匪的威胁。这些安保人员角色使用巡警的职业模板。调查人员则是便衣侦探，负责为公司客户解决各种异常事件阻止谋杀事件寻找失踪的人员等等。",
    "【7】\n【精神病医生（古典）】\n【信誉】：10-60\n【职业属性】：教育×4\n【本职技能】：法律，聆听，医学，外语，精神分析，心理学，科学（生物学，化学）。\n【介绍】：\n在1920年代，“精神病医生”这个词专用来称呼治疗精神失常的医生（也就是早期的精神科医生）。精神分析在当时的美国鲜为人知，而且它的基本内容都是性生活和如厕训练之类令大众不齿的东西。精神病学，一种正规的从行为主义发展来的医学理论则要普及得多。精神病医生精神科医生和神经科医生还经常爆发激烈的论战。",
    "【8】\n【动物训练师】\n【信誉】：10-40\n【职业属性】：教育×2＋外貌或意志×2\n【本职技能】：跳跃，聆听，自然，心理学，科学（动物学），潜行，追踪，任意一项其他个人或时代特长。\n【介绍】：\n动物训练师可能在电影工作室巡回马戏团马厩工作或自由工作。不管是训练导盲犬狮子钻火圈，他们工作时基本要独自一人长时间近距离地照看这些动物。动物训练师可以像对人一样对动物使用「心理学」技能。",
    "【9】\n【文物学家（原作向）】\n【信誉】：30-70\n【职业属性】：教育×4\n【本职技能】：估价，技艺（任一），历史，图书馆，外语，一项社交技能（魅惑、话术、恐吓、说服），侦查，任意一项其他个人或时代特长。\n【介绍】：\n文物学家也许是调查员可以从事的最具有洛夫克拉夫特风格的职业：那些历久弥新的的卓越作品湮没在古代传说中的神奇力量，总能使他们乐在其中。独立的收入使文物学家能够研究古旧晦涩的文物，或者根据自己的兴趣爱好集中探寻特别的种类。他们通常有着欣赏的眼光敏锐的头脑，和讽刺无知自大贪婪者的愚蠢时尖酸刻薄的幽默。",
    "【10】\n【古董商】\n【信誉】：30-50\n【职业属性】：教育×4\n【本职技能】：会计，估价，汽车驾驶，两项社交技能（魅惑、话术、恐吓、说服），历史，图书馆，导航。\n【介绍】：\n古董商通常自己开店，从自己所在的地方转卖物品，或继续扩展业务范围，通过倒卖物品到城市商店赚取利润。",
    "【11】\n【考古学家（原作向）】\n【信誉】：10-40\n【职业属性】：教育×4\n【本职技能】：估价，考古，历史，外语，图书馆，侦查，机械维修，导航或科学（任一：如化学、物理、地理等）。\n【介绍】：\n考古学家研究探索历史的痕迹。主要来说，是对人类历史相关的物质资料进行各种鉴识检查分析。这项工作包含辛苦细致的研究，更不必提情愿亲自下斗铲土的决心。在1920年代，成功的考古学家会被当成著名冒险家与探险家，名利双收。有人运用科学方法考古，不过更多的人对付老祖宗的秘密时喜好暴力破解的办法，甚至祭出炸药，这种碉堡了的办法现代人可是很难看得惯的。",
    "【12】\n【建筑师】\n【信誉】：30-70\n【职业属性】：教育×4\n【本职技能】：会计，技艺（技术制图），法律，母语，计算机或图书馆，说服，心理学，科学（数学）。\n【介绍】：\n建筑师掌握设计和营造建筑的知识，不论是个人房屋的改造还是造价数百万美元的地标工程。建筑师与项目经理紧密合作，负责监督施工全程。建筑师必须了解当地的规划法律，健康和安全法规，和基础的公众安全原则。他们既可以在大公司工作，也可以自由工作，这在很大程度上取决于【信誉】。在1920年代，许多人尝试在自家或小办公室单干。",
    "【13】\n【艺术家】\n【信誉】：9-50\n【职业属性】：教育×2＋敏捷或意志×2\n【本职技能】：技艺（任一），历史或自然，一项社交技能（魅惑、话术、恐吓、说服），外语，心理学，侦查，任意两项其他个人或时代特长。\n【介绍】：\n艺术家在这里可以是画家，雕塑家等等。他们有时沉浸于自己虚幻的想象当中，有时又沐浴在激发热情和理解的灵感之下。不论是否天资优秀，艺术家的内心必须足够强大，这样才能战胜生涯起步时的障碍和挑剔的眼光，并且在自己小有名气以后继续努力。有些艺术家对物质生活是否丰富并不在乎，而有些则有着强烈的创业倾向。",
    "【14】\n【精神病院看护】\n【信誉】：8-20\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：闪避，格斗（斗殴），急救，两项社交技能（魅惑、话术、恐吓、说服），聆听，心理学，潜行。\n【介绍】：\n尽管少数富有的人会选择私人疗养院，大多精神病患者最终会被安置到州县设置的定点医院。这些地方除了医生护士以外，还会有一支看护队伍。选聘看护的时候，力量和体格往往比医学知识更被看重。",
    "【15】\n【运动员】\n【信誉】：9-70\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：攀爬，跳跃，格斗（斗殴），骑乘，一项社交技能（魅惑、话术、恐吓、说服），游泳，投掷，任意一项其他个人或时代特长。\n【介绍】：\n运动员可能效力于职业的棒球足球板球或者篮球队伍。这支队伍也许是大联盟队伍，有着稳定工资，参加的比赛万人瞩目；或者是众多小联盟队伍之一，尤其是在1920年代的棒球界。这些队伍往往寄于大联盟队伍篱下，各方面都受其管理，工资更是刚够运动员糊口又不至于让他们跳槽的水平。成功的运动员在自己的专业领域也会拥有相当的声誉。",
    "【16】\n【作家（原作向）】\n【信誉】：9-30\n【职业属性】：教育×4\n【本职技能】：技艺（文学），历史，图书馆，自然或神秘学，外语，母语，心理学，任意一项其他个人或时代特长。\n【介绍】：\n作家不同于记者，他们用文字定义和探讨人们的社会生活，尤其是人们的情感变化。他们的劳动通常孤立而又自我中心：虽然以前写作是个能稳拿工资的行当，但如今只靠写作发大财的人屈指可数。作家的工作习惯相差极大。通常作家们会花费数月乃至数年的时间调查取材，为新书的创作做准备；然后闭门谢客，投入紧张的创作。",
    "【17】\n【酒保】\n【信誉】：8-25\n【职业属性】：教育×2＋外貌×2\n【本职技能】：会计，两项社交技能（魅惑、话术、恐吓、说服），格斗（斗殴），聆听，心理学，侦查，任意一项其他个人或时代特长。\n【介绍】：\n酒保虽然不一定是酒吧的掌柜，却一定是所有客人的朋友。对客人们的好声气，一部分来说是出于他们的职业或者业务，而更多的来说则是达到目的的一种手段。1920年代，由于禁酒令的存在，酒保变成了非法的职业；但是遍地开花的黑酒吧又不能没有酒保，结果就是酒保仍然不愁找不到活干。",
    "【18】\n【猎人】\n【信誉】：20-50\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：射击，聆听或侦查，自然，导航，外语或生存（任一），科学（生物学或植物学），潜行，追踪。\n【介绍】：\n猎人是优秀的追踪者和狩猎者，通常靠为富裕的客户捕猎为生。绝大多数猎人会对地球上某一个部分的情况烂熟于心，比如加拿大森林非洲草原等等。有些人可能从事盗猎活动，例如为私人收藏家捕捉珍稀动物，或者贩卖受保护的动物和违反道德的动物制品，如兽皮象牙之类.",
    "【19】\n【书商】\n【信誉】：20-40\n【职业属性】：教育×4\n【本职技能】：会计，估价，汽车驾驶，历史，图书馆，母语，外语，一项社交技能（魅惑、话术、恐吓、说服）。\n【介绍】：\n书商可能拥有自己的店面或者利基（小众）邮购服务，也可能辗转全国甚至海外专门经销书籍。许多人拥有富有的，能提供利润丰厚又稀罕的工作的固定客户。",
    "【20】\n【赏金猎人】\n【信誉】：9-30\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：汽车驾驶，电子学或电气维修，格斗或射击，一项社交技能（魅惑、话术、恐吓、说服），法律，心理学，追踪，潜行。\n【介绍】：\n赏金猎人捉拿罪犯并将他们交给正义去审判。最常见的情况是受保释人的委托去缉捕逃狱者。赏金猎人们为了自己的猎物可以不择手段，几乎不会考虑其他人的正当权益之类细枝末节的东西。非法闯入威胁肢体暴力，都是赏金猎人屡试不爽的秘技。现在这些秘技还包括了电话窃听黑客操作和其他的秘密监控。",
    "【21】\n【拳击手、摔跤手】\n【信誉】：9-60\n【职业属性】：教育×2＋力量×2\n【本职技能】：闪避，格斗（斗殴），恐吓，跳跃，心理学，侦查，任意两项其他个人或时代特长。\n【介绍】：\n拳击手和摔跤手各分为职业和业余两种。职业拳击手和职业摔角手的活动由外部利益支持的赞助人安排，并有合同约束。他们还要进行全日制的工作和训练。业余拳击的竞赛种类非常丰富，同时它也是那些想成为职业拳手的人的训练场。不过也有业余和准职业的选手靠参加黑市拳击赛谋生，举办这些比赛的通常是本地的黑社会或者是从中渔利的庄家。",
    "【22】\n【管家、男仆、女仆】\n【信誉】：9-40\n【职业属性】：教育×4\n【本职技能】：会计或估价，技艺（任一：如烹饪、裁缝、理发），急救，聆听，外语，心理学，侦查，任意一项其他个人或时代特长。\n【介绍】：\n服务业人员。管家通常为一个大家庭打理家事。传统上，他负责的范围包括厨房仆人中位置最高。一般男管家还要负责管理其他的男仆（女管家类似）。更多的职责则听候主人差遣。男仆和女仆则为主人提供贴身服务，包括管理主人的服装准备浴室和担任私人助理。助理的工作则包括安排旅行日程财等。",
    "【23】\n【神职人员】\n【信誉】：9-60\n【职业属性】：教育×4\n【本职技能】：会计，历史，图书馆，聆听，外语，一项社交技能（魅惑、话术、恐吓、说服），心理学，任意一项其他技能。\n【介绍】：\n神职人员通常担任一个教区的牧师，或是经过分配外出传教，尤其是去国外（见传教士）。不同的教会工作的侧重点和组织结构各不相同，如天主教会的牧师可能上升到主教大主教和红衣主教，而一个卫理公会的牧师则会升职到教区主管和主教。有些教职人员在教堂接受医生律师学者的专业培训。这样的调查员应该选择最符合自己工作的职业模板。",
    "【24】\n【程序员、电子工程师（现代）】\n【信誉】：10-70\n【职业属性】：教育×4\n【本职技能】：计算机，电气维修，电子学、图书馆，科学（数学），侦查，任意两项其他个人或时代特长。\n【介绍】：\n（现代）计算机程序员通常是设计编写测试调试和维护计算机程序源代码的职业。他们精通从形式逻辑到系统平台（程序运行环境）的各种知识，可能是自由工作者，也可能供职于软件开发部门。计算机技术人员负责计算机系统和网络的开发和维护工作，经常与其他人员（如项目经理）合作来保证系统的完整稳定和正常提供所需功能。",
    "【25】\n【黑客/骇客（现代）】\n【信誉】：10-70\n【职业属性】：教育×4\n【本职技能】：计算机，电气维修，电子学，图书馆，侦查，一项社交技能（魅惑、话术、恐吓、说服），任意两项其他技能。\n【介绍】：\n计算机黑客则利用计算机和计算机网络为手段，进行干扰或破坏以达成政治目的（有时被称为“政治黑客”）或获取非法利益。达成目标的手段主要是非法入侵计算机和其他用户帐户，目的则可能包括篡改网页垃圾邮件炸弹。",
    "【26】\n【牛仔】\n【信誉】：9-20\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：闪避，格斗或射击，急救或自然，跳跃，骑乘，生存（任一），投掷，追踪。\n【介绍】：\n牛仔在西部的牧区和牧场工作。有些人拥有自己的牧场，更多的则是在各处打工为生。想赚大钱的牛仔会去冒着丢胳膊少腿乃至送命的危险参加牛仔巡回赛，通过旅行获取名誉。在1920年代，一些牛仔能在好莱坞找到西部片替身演员和群众演员的工作，例如怀特•厄普就曾为西部电影担任顾问。在现代，有些牧场也对想要体验一把牛仔生活的游客开放。",
    "【27】\n【工匠】\n【信誉】：10-40\n【职业属性】：教育×2＋敏捷×2\n【本职技能】：会计，技艺（任二），机械维修，自然，侦查，任意两项其他个人或时代特长。\n【介绍】：\n工匠也可能被人叫做师傅或大师，是擅长对各种材料进行手工加工的人。通常都是才能出众的人，有的凭借自己的艺术作品出名，有的则会服务于自己的社区。",
    "【28】\n【罪犯-刺客】\n【信誉】：30-60\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：乔装，电气维修，格斗，射击，锁匠，机械维修，潜行，心理学。\n【介绍】：\n杀手是地下世界的冷血夺命者。这是一项严谨的活计，他们从外地受雇杀人，接近目标，果断下手，又迅速离开。杀手通常很难融入社会，因为很多杀手行为总是很刻板，其他人很容易以为他们不近人情。但是另一方面，他们也会结婚生子，在其他方面和普通人没有什么不同。",
    "【29】\n【罪犯-银行劫匪】\n【信誉】：5-75\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：汽车驾驶，电气维修或机械维修，格斗，射击，恐吓，锁匠，操作重型机械，任意一项其他个人或时代特长。\n【介绍】：\n有些则组成分工明确，会详细调查并制定计划的犯罪组织。",
    "【30】\n【罪犯-打手、暴徒】\n【信誉】：5-30\n【职业属性】：教育×2＋力量×2\n【本职技能】：汽车驾驶，格斗，射击，两项社交技能（魅惑、话术、恐吓、说服），心理学，潜行，侦查。\n【介绍】：\n罪犯可能为别人工作，后者通常是“匪帮”或罪犯家族。自由犯罪者则往往被称为抢劫犯打手罪组织豢养，不过团伙上层出事的时候，倒霉的往往是他们这些喽啰。对于他们来说，嘴紧和忠心属于职业道德。",
    "【31】\n【罪犯-窃贼】\n【信誉】：5-40\n【职业属性】：教育×2＋敏捷×2\n【本职技能】：估价，攀爬，电气维修或机械维修，聆听，锁匠，妙手，潜行，侦查。\n【介绍】：\n罪犯的体格和相貌形形色色，有些是纯粹碰运气伺机行事，比如扒手.",
    "【32】\n【罪犯-欺诈师】\n【信誉】：10-65\n【职业属性】：教育×2＋外貌×2\n【本职技能】：估价，技艺（表演），法律或外语，聆听，两项社交技能（魅惑、话术、恐吓、说服），心理学，妙手。\n【介绍】：\n欺诈师通常都是油嘴滑舌的人物。他们或单独或集体出没在富裕的人家和社区周边，诈取他们来之不易的钱财。许多骗局复杂精妙，诈骗团伙会倾巢出动乃至租用建筑；有些则不需要这么麻烦，只要一个骗子几分钟就能搞定。",
    "【33】\n【罪犯-独行罪犯】\n【信誉】：5-65\n【职业属性】：教育×2＋敏捷或外貌×2\n【本职技能】：技艺（表演）或乔装，估价，一项社交技能（魅惑、话术、恐吓、说服），格斗或射击，锁匠或机械维修，潜行，心理学，侦查。\n【介绍】：\n也可能单打独斗，如果成功的报酬值得去费力冒险，才会和别人搭伙。",
    "【34】\n【罪犯-女飞贼（古典）】\n【信誉】：10-80\n【职业属性】：教育×2＋外貌×2\n【本职技能】：技艺（任意），两项社交技能（魅惑、话术、恐吓、说服），格斗（斗殴）或射击（手枪），汽车驾驶，聆听，潜行，任意一项其他个人或时代特长。\n【介绍】：\n女飞贼是名为专业大盗的女人。大部分都是独立行动，也有对自己的男伴言听计从的时候。不过这也不一定，实际上情况可能完全相反，她完全可以在干了某一票以后就卷走所有现金和皮草溜之大吉。",
    "【35】\n【罪犯-赃物贩子】\n【信誉】：20-40\n【职业属性】：教育×2＋外貌×2\n【本职技能】：会计，估价，技艺（伪造），历史，一项社交技能（魅惑、话术、恐吓、说服），图书馆，侦查，任意一项其他技能。\n【介绍】：\n赃物贩子，顾名思义是买卖偷抢来的财产，通常是收购赃物并转手卖给其他罪犯或（无意中）守法的顾客。主要来说，他们是小偷和买家的中间人，有时也会从交易中收取提成；不过更常见的还是以极低的价格直接收购赃物。",
    "【36】\n【罪犯-赝造者】\n【信誉】：20-60\n【职业属性】：教育×4\n【本职技能】：会计，估价，技艺（伪造），历史，图书馆，侦查，妙手，任意一项其他个人或时代特长（如计算机）。\n【介绍】：\n赝造者是地下世界的艺术家，专门从事伪造官方文件契约转让书，并提供伪造的签名。初学者只能做做小贼的假身份证，而顶级的赝造者连印假币的铸模都能做。",
    "【37】\n【罪犯-走私者】\n【信誉】：20-60\n【职业属性】：教育×2＋外貌或敏捷×2\n【本职技能】：射击，聆听，导航，一项社交技能（魅惑、话术、恐吓、说服），汽车驾驶或驾驶（飞行器或船），心理学，妙手，侦查。\n【介绍】：\n走私一直是一个有利可图的高风险行当。走私者往往有一个合法的表面职业，比如船长飞行员或商人，以掩盖他们非法运输的行为。",
    "【38】\n【罪犯-混混】\n【信誉】：3-10\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：攀爬，一项社交技能（魅惑、话术、恐吓、说服），格斗，射击，跳跃，妙手，潜行，投掷。\n【介绍】：\n街头混混一般都是些小年轻，弄不好还在寻觅加入真正黑帮的契机。不过他们的本事也就限于偷车，盗窃商店货物，抢钱或者夜盗。",
    "【39】\n【教团首领】\n【信誉】：30-60\n【职业属性】：教育×4\n【本职技能】：会计，两项社交技能（魅惑、话术、恐吓、说服），神秘学，心理学，侦查，任意其他两项其他个人特长。\n【介绍】：\n美国的新兴宗教层出不穷。直到现在，也还有从新英格兰超验主义到“天父的儿女”等等许多种类。教团首领有的创立了严格的教条并且对信徒推行，另一些则仅仅是垂涎于信徒的金钱和权势。在1920年代，各种诱惑性的新兴宗教团体纷纷涌现。有些采取基督教的形式，有些则混杂了东方的神秘主义和神秘学的仪式。",
    "【40】\n【除魅师（现代）】\n【信誉】：20-50\n【职业属性】：教育×4\n【本职技能】：两项社交技能（魅惑、话术、恐吓、说服），汽车驾驶，格斗（斗殴）或射击，历史，神秘学，心理学，潜行。※经KP允许 可用催眠替换其中一项。\n【介绍】：\n除魅师的工作是说服（或者强迫）一个人放弃自己的信仰或是对宗教团体他们一般受雇于深陷教团之类组织的人的亲属，任务就是解救对方（通常靠绑架），并通过心理学手段使他们割断与原来教团的联系（“控制”）。也有不那么激烈的除魅师，他们的工作对象则是那些自愿离开教团的人，为他们完全地退出教团进行有效的指导。",
    "【41】\n【设计师】\n【信誉】：20-60\n【职业属性】：教育×4\n【本职技能】：会计，技艺（摄影），技艺（任一），计算机或图书馆，机械维修，心理学，侦查，任意一项其他个人特长。\n【介绍】：\n设计师的工作包括许多方面，从时装到家具或是其他任何东西。他们自由工作，为设计工作室和企业设计产品流程法律游戏图像等等。调查员特定的设计方向也会影响他们对专业技能的选择，如果需要的话要进行调整。",
    "【42】\n【业余艺术爱好者（原作向）】\n【信誉】：50-99\n【职业属性】：教育×2＋外貌×2\n【本职技能】：技艺（任一），射击，外语，骑乘，一项社交技能（魅惑、话术、恐吓、说服），任意三项其他个人或时代特长。\n【介绍】：\n业余艺术爱好者靠经济自立遗产继承信托基金或者其他各种来源保障自己的生活开支，没有必要自己工作。如果经济条件足够好，他们甚至可以雇佣专业的经济顾问来打理自己的产业。他们可能有很高的学历，但不一定是真才实学；优越的经济条件使得他们性情古怪，口无遮拦。在1920年代，这些人可能会被时人称为“摩登女郎”或者“公子哥儿”。",
    "【43】\n【潜水员】\n【信誉】：9-30\n【职业属性】：教育×2＋敏捷×2\n【本职技能】：潜水，急救，机械维修，驾驶（船），科学（生物），侦查，游泳，任意一项其他个人或时代特长。\n【介绍】：\n潜水员可能在军队执法机构或海绵采集海上救援环境保护甚至水下寻宝的民间机构工作。",
    "【44】\n【医生（原作向）】\n【信誉】：30-80\n【职业属性】：教育×4\n【本职技能】：急救、医学、外语（拉丁文）、心理学、科学（生物学，制药），任两种其他学术或个人特长。\n【介绍】：\n医生这里可能是指全科医生外科医生其他专科医生或者独立医学研究员。除去个人的目标以外，救死扶伤获得财富和荣誉提升公众的理性意识和科学素养也常常是医生的理想。农村和小城镇的卫生院是全科医生的舞台，而大城市的各大医院则是高手如云，集聚了众多专攻病理学毒理学整形外科脑外科等领域的专家。有些医生也可能担任全职或兼职的法医，进行尸检。",
    "【45】\n【流浪者】\n【信誉】：0-5\n【职业属性】：教育×2＋外貌或敏捷或力量×2\n【本职技能】：攀爬，跳跃，聆听，导航，一项社交技能（魅惑、话术、恐吓、说服），潜行，任意两项其他个人或时代特长。\n【介绍】：\n相对于那些因贫困而苦恼的人，流浪者选择四处漂泊的生活，可能是出于社会哲学经济的原因，或只是渴望摆脱社会的约束。流浪汉需要工作，有时几天或几个月，但他们应对问题时往往选择流动和孤立，而不是舒适和亲近。在美国，这种情况尤其常见，只要旅行本身没有什么危险，就会有人选择漂泊为生。",
    "【46】\n【司机-私人司机】\n【信誉】：10-40\n【职业属性】：教育×2＋敏捷×2\n【本职技能】：汽车驾驶，两项社交技能（魅惑、话术、恐吓、说服），聆听，机械维修，导航，侦查，任意一项其他个人或时代特长。\n【介绍】：\n私人司机则是直接受雇于个人或企业，或者是专门提供连人带车的私人司机业务的中介机构。",
    "【47】\n【司机-司机】\n【信誉】：9-20\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：会计，汽车驾驶，聆听，一项社交技能（魅惑、话术、恐吓、说服），机械维修，导航，心理学，任意一项其他个人或时代特长。\n【介绍】：\n专职司机可能为企业个人工作，也可能拥有自己的出租车或货车。",
    "【48】\n【司机-出租车司机】\n【信誉】：9-30\n【职业属性】：教育×2＋敏捷×2\n【本职技能】：会计，汽车驾驶，电气维修，话术，机械维修，导航，侦查，任意一项其他个人或时代特长。\n【介绍】：\n出租车司机可能属于大大小小的出租车公司，也可能靠自己的车和证件运营（在美国，需要出租车牌照）。出租车公司负责为出租车司机登记车辆并分配调度，方便司机自由揽客。出租车上必须统一安装计价器，并由出租车协会进行定期检查。通常司机还要通过警方的背景调查，获得特殊的驾驶许可证。",
    "【49】\n【编辑】\n【信誉】：10-30\n【职业属性】：教育×4\n【本职技能】：会计，历史，母语，两项社交技能（魅惑、话术、恐吓、说服），心理学，侦查，任意一项其他个人或时代特长。\n【介绍】：\n编辑的工作包括审核记者的稿件，撰写报刊社论，应对各种突发事件到了截稿时间要催稿，编辑工作只好偶尔为之啦。大型报社的编辑数量众多，包括比起新闻编辑更多参与业务运营的主编。其他编辑专门负责时尚体育或者其他板块。许多小报可能就只有一个编辑，他甚至有可能就是报社的业主或者唯一的全职员工。",
    "【50】\n【政府官员】\n【信誉】：50-90\n【职业属性】：教育×2＋外貌×2\n【本职技能】：魅惑，历史，恐吓，话术，聆听，母语，说服，心理学。\n【介绍】：\n以民选方式选举出来的政府官员享有与他们的职位相符的声望。小城市的市长和城镇的镇长之类，他们的影响力基本出不了城镇的范围，而且这样的职务基本上是兼职的，报酬也很少。大城市的市长，工资就相当可观了，而且还能把自己的城市管理得像小王国一样，影响力和权力比所在州的州长还要大。州议会的众参两院议员是相当有面子的职位。",
    "【51】\n【工程师】\n【信誉】：30-60\n【职业属性】：教育×4\n【本职技能】：技艺（技术制图），电气维修，图书馆，机械维修，操作重型机械，科学（工程学，物理），任意一项其他个人或时代特长。\n【介绍】：工程师精通机械和电气设备，可能在民间或军工企业工作，也可能是个发明家。他们擅长应用科学、数学知识和丰富的创造思维，解决各种技术问题。\n",
    "【52】\n【艺人】\n【信誉】：9-70\n【职业属性】：教育×2＋外貌×2\n【本职技能】：技艺（表演类，如表演、演唱、喜剧等），乔装，两项社交技能（魅惑、话术、恐吓、说服），聆听，心理学，任意两项其他个人或时代特长。\n【介绍】：\n艺人包括小丑歌手舞蹈演员喜剧演员杂耍艺人魔术师，各种以在人前表演谋生的人。他们乐于向更多的人表现自己的能力，并期待观众回报的掌声。在1920年代，这一职业并不受人尊重。不过1920 年代好莱坞明星的高薪彻底改变了很多人的想法，现在这个职业背景已经通常被视作是优势了。",
    "【53】\n【探险家（古典）】\n【信誉】：55-80\n【职业属性】：教育×2＋外貌或敏捷或力量×2\n【本职技能】：攀爬或游泳，射击，历史，跳跃，自然，导航，外语，生存。\n【介绍】：\n在20世纪早期，这世界还有许多地区尚未有人涉足，而探索这些地方正是探险家的工作。这种令人兴奋不已的生活方式，其经济来源则是科学界的赞助私人的捐赠博物馆的委托和报纸杂志图书电影的版权等等。黑非洲的大部分仍然不为人知，同样的地方还包括了南美的马托格罗索高原，澳大利亚的大沙沙漠，撒哈拉和阿拉伯沙漠，和亚洲的茫茫戈壁。尽管南北极点已经被探险家征服了。",
    "【54】\n【农民】\n【信誉】：9-30\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：技艺（耕作），汽车驾驶（或运货马车），一项社交技能（魅惑、话术、恐吓、说服），机械维修，自然，操作重型机械，追踪，任意一项其他个人或时代特长。\n【介绍】：\n农民可能自己拥有土地，自己从事农牧业，也可能是受雇在农场工作。农业劳动繁重而枯燥，特别适合那些喜欢户外体力劳动的人。1920年代是美国城镇人口超过农村人口的首个十年。从这时起一直到现在，自耕农民都在受到规模化农业企业和剧烈波动的农产品市场的双重冲击。",
    "【55】\n【联邦探员】\n【信誉】：20-40\n【职业属性】：教育×4\n【本职技能】：汽车驾驶，格斗（斗殴），射击，法律，说服，潜行，侦查，任意一项其他个人或时代特长。\n【介绍】：\n联邦执法机构和特工种类各异。有些身着制服，比如美国司法部的人员；另外一些则穿便服，工作内容也类似警探，比如联邦调查局的人员。",
    "【56】\n【消防员】\n【信誉】：9-30\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：攀爬，闪避，汽车驾驶，急救，跳跃，机械维修，操作重型机械，投掷。\n【介绍】：\n消防员是公职人员，通常为所管辖的社区服务。他们夜以继日地工作，或者连续几天的倒班工作，吃住包括娱乐活动都要局限在消防局里。消防员的管理结构类似军队，职位包括中尉上尉和局长等等。",
    "【57】\n【驻外记者】\n【信誉】：10-40\n【职业属性】：教育×4\n【本职技能】：历史，外语，母语，聆听，两项社交技能（魅惑、话术、恐吓、说服），心理学，任意一项其他个人或时代特长。\n【介绍】：\n驻外记者是新闻界的精英人才。他们拿着固定工资，靠报销单环游全世界。在1920年代，驻外记者通常供职于大型报社广播电台或者国家级通讯社。当代的驻外记者也可能自由撰稿或者为电视台网络通讯社和国际新闻通讯社工作。这个职业的工作内容五花八门，经常能激动人心。不过自然灾害政治动荡和战争也会成为驻外记者报道的主要内容，工作也不总是一帆风顺。",
    "【58】\n【法医】\n【信誉】：40-60\n【职业属性】：教育×4\n【本职技能】：外语（拉丁文），图书馆，医学，说服，科学（生物学，鉴证，制药），侦查。\n【介绍】：\n法医是一个高度专门化的职业，大多数法医为市县或州执法机构工作。工作内容包括尸体解剖，推定死因，并为公诉人提供建议。法医也常常会在刑事审判中出庭提供证言。",
    "【59】\n【赌徒】\n【信誉】：8-50\n【职业属性】：教育×2＋外貌或敏捷×2\n【本职技能】：会计，技艺（表演），两项社交技能（魅惑、话术、恐吓、说服），聆听，心理学，妙手，侦查。\n【介绍】：\n赌徒是罪犯世界里最花哨的一群人。他们衣着光鲜，不论朴实还是华丽都魅力四射。不论是靠赛马、纸牌游戏还是其他赌博方式，他们总是要凭自己的运气过活。老练的赌徒会频繁地光顾犯罪组织开设的地下赌场。低级的赌徒则出入于狭窄的小巷，在骰子房耍弄灌铅的骰子，或者是挤坐在阴暗的台球室里。",
    "【60】\n【黑帮-黑帮老大】\n【信誉】：60-95\n【职业属性】：教育×2＋外貌×2\n【本职技能】：格斗，射击，法律，聆听，两项社交技能（魅惑、话术、恐吓、说服），心理学，侦查。\n【介绍】：\n黑帮可能是整个城市、一部分城市的大佬，老板总管业务，负责交易，并要就各种各样的问题给马仔们拿主意。更重要的是，老板可以各种高人一等，只要能找到马仔或者小弟去干的事，他基本是不肯污了自己的手去做的。黑社会在1920年代上升为突出的社会问题。现在的黑帮老大也需要大量的小弟来负责保卫、推广、在街道里推行自己的业务。",
    "【61】\n【黑帮-马仔】\n【信誉】：9-20\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：汽车驾驶，格斗，射击，两项社交技能（魅惑、话术、恐吓、说服），心理学，任意两项其他个人或时代特长。\n【介绍】：\n也可能只是给这些大佬打工的马仔。马仔们通常有自己的保护范围，比如监管非法运输和收取保护费等等。虽然大部分黑帮是按来源的民族划分——如爱尔兰裔、意大利裔、非洲裔和犹太裔，黑帮的成员仍然可能是任何民族。除去贩私酒和贩毒以外，卖淫、保护、赌博、腐败等等都是这些犯罪组织的业务范围。",
    "【62】\n【绅士、淑女】\n【信誉】：40-90\n【职业属性】：教育×2＋外貌×2\n【本职技能】：技艺（任一），两项社交技能（魅惑、话术、恐吓、说服），射击（步枪/霰弹枪），历史，外语（任一），导航，骑乘。\n【介绍】：\n绅士淑女指的是有良好的教养品行、举止彬彬有礼的人。通常用来称呼上流社会（通过继承或津贴）拥有相当财富的人。在上世纪20年代，这样的人至少要有一个仆人（管家、男仆、女仆、私人司机），还要有城市或乡村的宅第。家庭的富有并重要，因为家庭的社会地位往往比财产更被上流社会所看重。",
    "【63】\n【游民】\n【信誉】：0-5\n【职业属性】：教育×2＋外貌或敏捷×2\n【本职技能】：技艺（任一），攀爬，跳跃，聆听，锁匠或妙手，导航，潜行，任意一项其他个人或时代特长。\n【介绍】：\n游民只有少数的人愿意去当，虽然失业的人、醉倒在阴沟里的醉鬼到处都是。和流浪者只会在必需时才工作不同，游民的工作本身就是流浪。他们不断地坐火车旅行，从一个城市辗转到另一个城市，他们是身无分文的诗人、漂泊者，铁路上的探索者、冒险者和盗贼。但是铁路上的生活一样充满危险。且不说穷困潦倒、无家可归，还要面对来自警察、周围居民和铁路员工的敌意。",
    "【64】\n【勤杂护工】\n【信誉】：6-15\n【职业属性】：教育×2＋力量×2\n【本职技能】：电气维修，一项社交技能（魅惑、话术、恐吓、说服），格斗（斗殴），急救，聆听，机械维修，心理学，潜行。\n【介绍】：\n勤杂护工在医院的工作包括倒垃圾、打扫房间、运送病人，还有一些其他乱七八糟的工作。总之对他们的要求不比对看门人多多少。",
    "【65】\n【记者(原作向)-调查记者】\n【信誉】：9-30\n【职业属性】：教育×4\n【本职技能】：技艺（艺术或摄影），一项社交技能（魅惑、话术、恐吓、说服），历史，图书馆，母语，心理学，任意两项其他个人或时代特长。\n【介绍】：\n记者用文字对当天的新闻事件进行报导与评论，一天之内就要完成一个作家一周的工作量。他们通常为报纸、杂志、广播电台、电视台或者新闻网站撰稿。优秀的调查记者在报道事件的同时，即使面对丑恶，也能保持自身的清廉正直。恶心的记者则被现实所压倒，最终丧失自己的节操，肆意操纵文字歪曲真相。",
    "【66】\n【记者(原作向)-通讯记者】\n【信誉】：9-30\n【职业属性】：教育×4\n【本职技能】：技艺（表演），历史，聆听，母语，一项社交技能（魅惑、话术、恐吓、说服），心理学，潜行，侦查。\n【介绍】：\n通讯记者则是新闻传媒行业大军中的一员。大部分记者从事实地工作，包括走访见证人、查看记录、收集叙述。有些记者被安排专门追踪警界、体育界或商界的热点新闻，其他人则是负责社会事件乃至园艺俱乐部之类的事情。通讯记者都会携带记者证，不过记者证除了各通讯社用来识别自己的雇员以外没有太大的作用。",
    "【67】\n【法官】\n【信誉】：50-80\n【职业属性】：教育×4\n【本职技能】：历史，恐吓，法律，图书馆，聆听，母语，说服，心理学。\n【介绍】：\n法官是主持审判全过程的人，可能单独工作或是和同事组成合议庭。一般是推选或任命制，工作年限也分定期和终身。有的人是初出茅庐就当了法官，而其余的绝大多数，不论是在联邦最高法院还是遥远西部小镇的法官，其实至少都是经过注册的律师。",
    "【68】\n【实验室助理】\n【信誉】：10-30\n【职业属性】：教育×4\n【本职技能】：计算机或图书馆，电气维修，外语，科学（化学和任意两项），侦查，任意一项其他个人特长。\n【介绍】：\n实验室助理在科研环境中工作，在首席科学家的监督下进行实验和行政工作。研究内容可能依首席科学家的研究学科而变化。但基本都包括取样、测试、记录和分析数据、调整和进行实验、制备标本和样品、管理实验室的日常工作，和保护工作人员的健康与安全。",
    "【69】\n【工人-非熟练工人】\n【信誉】：9-30\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：汽车驾驶，电气维修，格斗，急救，机械维修，操作重型机械，投掷，任意一项其他个人或时代特长。\n【介绍】：\n工人这一大类职业包括工厂工人、纺织工人、码头工人、养路工人、矿工、建筑工人等等。工人分为两种类型：熟练工和非熟练工。普通的工人虽然技术不熟练，但是仍然长于使用电动工具、起重机和其他工厂设备。",
    "【70】\n【工人-伐木工】\n【信誉】：9-30\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：攀爬，闪避，格斗（链锯），急救，跳跃，机械维修，自然或科学（生物学或植物学），投掷。\n【介绍】：\n工人这一大类职业包括工厂工人、纺织工人、码头工人、养路工人、矿工、建筑工人等等。工人分为两种类型：熟练工和非熟练工。普通的工人虽然技术不熟练，但是仍然长于使用电动工具、起重机和其他工厂设备。",
    "【71】\n【工人-矿工】\n【信誉】：9-30\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：攀爬，科学（地质），跳跃，机械维修，操作重型机械，潜行，侦查，任意一项其他个人或时代特长。\n【介绍】：\n工人这一大类职业包括工厂工人、纺织工人、码头工人、养路工人、矿工、建筑工人等等。工人分为两种类型：熟练工和非熟练工。普通的工人虽然技术不熟练，但是仍然长于使用电动工具、起重机和其他工厂设备。",
    "【72】\n【律师】\n【信誉】：30-80\n【职业属性】：教育×4\n【本职技能】：会计，法律，图书馆，两项社交技能（魅惑、话术、恐吓、说服），心理学，两项其他技能。\n【介绍】：\n律师或法律顾问精通他们所在地区的法律，擅长把抽象的法学理论知识联系起来，为客户解决法律方面的疑难，担任辩护代理、法律顾问的工作，为客户提供解决办法。可能受托处理个人案件、接受法院指定，也可能专门为某个富裕客户或公司服务。在美国，“律师”一词一般只指辩护律师。在英国，“律师”一词则包括高级律师、初级律师还有一些执法机构。",
    "【73】\n【图书馆管理员（原作向）】\n【信誉】：9-35\n【职业属性】：教育×4\n【本职技能】：会计，图书馆，外语，母语，任意四项其他个人特长或专业书籍主题。\n【介绍】：\n图书馆管理员在公共机构和图书馆工作，负责管理图书目录和书库，并处理图书借阅等。在现代，图书馆管理员还要负责管理视听资料、电子书库。一些大公司可能聘用图书馆管理员管理书库，偶尔还会有富有的图书藏家招收他们管理自己的私人藏书。",
    "【74】\n【技师】\n【信誉】：9-40\n【职业属性】：教育×4\n【本职技能】：技艺（木工、焊接、管道工等），攀爬，汽车驾驶，电气维修，机械维修，操作重型机械，任意两项其他个人或时代或技术特长。\n【介绍】：\n技师包括所有需要专业训练和作为学徒或实习生工作经验的职业，例如木工、石工、管道工、电工、设备安装工人、机修工人等等这些需要技术资质的职业。通常这些工人有自己的工会组织，会和承包人和雇主争取自己的权益。",
    "【75】\n【军官】\n【信誉】：20-70\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：会计，射击，导航，急救，两项社交技能（魅惑、话术、恐吓、说服），心理学，任意一项其他个人或时代特长。\n【介绍】：\n军官有严格的等级，许多等级还需要高等教育学历。各国武装部队都建立了人才培养系统，其中包括大学教育。在美国，许多大学开设军校生训练项目，可以让学员同时接受文化教育和军事训练。毕业的学员可以授以陆军或海军少尉军衔，并分派到各驻地。他们通常会为国家服役四年，之后可以退役复员。许多人有专门的任命，作为医生、律师和工程师工作。",
    "【76】\n【传教士】\n【信誉】：0-30\n【职业属性】：教育×2＋外貌×2\n【本职技能】：技艺（任一），急救，机械维修，医学，自然，一项社交技能（魅惑、话术、恐吓、说服），任意两项其他个人或时代特长。\n【介绍】：\n传教士云游到世界的各个角落，传播神的旨意，在文明的地方拯救“不幸的原始人”和“迷途的灵魂”。他们可能属于天主教、新教、伊斯兰教或者其他信仰系统，比如后期圣徒教会（摩门教）在欧美就有专门的传道所。有的传教士只凭自己的意志独立行动，有的则可能有教会以外的组织支持。基督教、伊斯兰教的传教者，佛教、印度教的法师，在全世界各个时代都能遇到。",
    "【77】\n【登山家】\n【信誉】：30-60\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：攀爬，急救，跳跃，聆听，导航，外语，生存（阿尔卑斯或类似），追踪。\n【介绍】：\n登山家一般都是利用业余时间和假期的运动员，只有少数攀登著名高山的人才会去寻找财力和设备的赞助。19世纪登山运动开始兴起，到了1920年代，所有美洲和阿尔卑斯地区的主要山峰都被一一征服。经过与西藏人的冗长谈判之后，外国登山队终于获准进入喜马拉雅高峰地区。到了现代，登山可以是休闲运动或职业选择。如果是后者，则工作内容包括教练、向导、运动员或救生员等。",
    "【78】\n【博物馆管理员】\n【信誉】：10-30\n【职业属性】：教育×4\n【本职技能】：会计，估价，考古，历史，图书馆，神秘学，外语，侦查。\n【介绍】：\n博物馆管理员可能负责大学或其他公共机构的大型设施，也可能负责小一些的博物馆，往往对本地的地质或者其他的内容颇有研究。",
    "【79】\n【音乐家】\n【信誉】：9-30\n【职业属性】：教育×2＋意志或敏捷×2\n【本职技能】：技艺（乐器），一项社交技能（魅惑、话术、恐吓、说服），聆听，心理学，四项其他技能。\n【介绍】：\n音乐家可能加入乐团、乐队或者独奏，演奏的乐器则可以是任何你能想象的种类。音乐家想出人头地十分困难，签约发布唱片就更难了。所以绝大多数音乐家都贫穷又无人关注，只靠街头卖艺勉强维持生计。少数幸运儿可以找到固定工作，比如在酒吧、宾馆或者市交响乐团弹钢琴。对更少的人来说，在正确的时间出现在正确的地点，再加上一点点天赋，就能获得巨大的成功和可观的财富。",
    "【80】\n【护士】\n【信誉】：9-30\n【职业属性】：教育×4\n【本职技能】：急救，聆听，医学，一项社交技能（魅惑、话术、恐吓、说服），心理学，科学（生物学，化学），侦查。\n【介绍】：\n护士是专业的医疗助理，通常在医院和疗养院之类的地方工作，或者和全科医生一起合作。一般来说，护士会协助健康人或病人进行保健或康复活动（或者临终关怀），虽然其他人若是有足够的力量、意志或者知识，完全不需要护士帮助的康复也是可能的。",
    "【81】\n【神秘学家】\n【信誉】：9-65\n【职业属性】：教育×4\n【本职技能】：人类学，历史，图书馆，一项社交技能（魅惑、话术、恐吓、说服），神秘学，外语，科学（天文），任意一项其他个人或时代特长 ※经KP允许 可以包含克苏鲁神话。\n【介绍】：\n神秘学家是钻研深奥秘密和神秘魔法的人。他们对超自然能力深信不疑，并竭尽所能靠他们的能力去了解这些东西。许多人对不同神秘哲学和魔法理论的知识面都相当广泛，有些甚至相信自己专注研究三十年真的成为了魔法师。需要指出的是，神秘学家熟知的基本上是“表面的魔法”——克苏鲁神话魔法的秘密对他们仍然是未知的，或者不过是古书上描述那些诱人的线索而已。",
    "【82】\n【旅行家】\n【信誉】：5-20\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：射击，急救，聆听，自然，导航，侦查，生存（任一），追踪。\n【介绍】：\n旅行家爱好户外，他们一年中大部分时间都呆在户外，并且一出门就是相当长的时间；通常有相当的捕鱼和狩猎技术，能在最恶劣的环境之中幸存下来。擅长的技术可能包括登山、捕鱼、滑雪、皮划艇、攀登和露营。旅行家可能在国家公园或素质拓展中心做野外向导和护林员，也可能是有其他经济来源能让他们不用工作就能以这种方式生活，也说不定只有在需要的时候才会回到文明社会。",
    "【83】\n【超心理学家】\n【信誉】：9-30\n【职业属性】：教育×4\n【本职技能】：人类学，技艺（摄影），历史，图书馆，神秘学，外语，心理学，任意一项其他个人或时代特长。\n【介绍】：\n超心理学家从不打算欣赏超常现象。相反，他们试图去观察，记录并研究这些实例。被叫做“捉鬼人”的他们利用技术手段来获取某人或某地点的超自然活动的证据，当然比起收集到实在的证据，更多的时候他们是在揭穿假冒和误认的超常现象。选择研究这个的人往往对不可视的神秘力量抱有相当的同情态度，并希望其他的科学家也能满意地点头肯定。",
    "【84】\n【药剂师】\n【信誉】：35-75\n【职业属性】：教育×4\n【本职技能】：会计，急救，外语（拉丁文），图书馆，一项社交技能（魅惑、话术、恐吓、说服），心理学，科学（制药，化学）。\n【介绍】：\n药剂师的管理一直以来都比医生更严格。所有的药剂师都要在各州注册，注册的条件则是高中毕业并至少在药学院学习三年。他们可能在医院或者药房工作，也可能自己开药房。",
    "【85】\n【摄影师-摄影师】\n【信誉】：9-30\n【职业属性】：教育×4\n【本职技能】：技艺（摄影），一项社交技能（魅惑、话术、恐吓、说服），心理学，科学（化学），潜行，侦查，任意两项其他个人或时代特长。\n【介绍】：\n摄影师大部分是自由工作者，可能制作广告电影或者在照相馆做肖像拍摄。其他一些摄像师则在报纸、电视和电影产业工作。摄影作为一种艺术形式已经产生相当长的时间了，精英的摄影师可以从艺术、新闻报道、野生动物保护等多种角度出发创作他们的作品。不管是哪种立意，他们都能获得名誉和报酬。",
    "【86】\n【摄影师-摄影记者】\n【信誉】：10-30\n【职业属性】：教育×4\n【本职技能】：技艺（摄影），攀爬，一项社交技能（魅惑、话术、恐吓、说服），外语，心理学，科学（化学），任意两项其他个人或时代特长。\n【介绍】：\n摄影记者本质上就是拿照相机，为拍摄的照片写配文的记者。在1920年代，新闻短片走上历史舞台。笨重的35mm摄像装备走遍全球各地，搜寻有价值的新闻轶事、体育赛事和泳装选美比赛。新闻片制作人员一般分为三类：一类是画面中的记者，另两个人则负责摄像和灯光等等。新闻中的声音则是在新闻稿完成以后在录音棚中录入完成的。",
    "【87】\n【飞行员-飞行员】\n【信誉】：20-70\n【职业属性】：教育×2＋敏捷×2\n【本职技能】：电气维修，机械维修，导航，操作重型机械，驾驶（飞行器），科学（天文），任意两项其他个人或时代特长。\n【介绍】：\n飞行员可以在美国邮政这样的企业工作，也可以在大大小小的民航公司做飞行人员。美国1926年之前没有对飞行员的职业要求,1926年航空商业法案通过之后才要求有执照。这个时代的多数飞行员从事嘉年华表演、特技飞行表演、乘飞机游玩或是小机场的空中的士等服务。也有飞行员在部队服现役。许多特技飞行员是在服役期间学会的驾驶飞机，有时仍然会被军队委派任务。",
    "【88】\n【飞行员-特技飞行员（古典）】\n【信誉】：30-60\n【职业属性】：教育×4\n【本职技能】：会计，电气维修，聆听，机械维修，导航，驾驶（飞行器），侦查，任意一项其他个人或时代特长。\n【介绍】：\n特技飞行员在嘉年华工作或者为大胆的消费者进行休闲飞行服务。参加有组织的飞行表演赛，不论是固定路线还是越野赛，往往都可以增加自己的知名度。在1920年代，好莱坞常常使用特技飞行员，飞机制造商也会录用一些飞行员为新机作测试。许多特技飞行员是在一次大战中掌握的飞行技术，所以许多人仍然在陆海空军或海岸警卫队服役；年轻的飞行员则基本上是在和平时期接受的训练或是自学成才。",
    "【89】\n【警方(原作向)-警探】\n【信誉】：20-50\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：技艺（表演）或乔装，射击，法律，聆听，一项社交技能（魅惑、话术、恐吓、说服），心理学，侦查，一项其他技能。\n【介绍】：\n警探可能指挥他的下属进行详尽的调查，但是很难有机会集中精力对付单独一个事件，在美国他们很可能要同时处理数十乃至上百的案件。警探工作最关键的部分是通过梳理证词、重建现场情况，摒弃伪证，从而收集足够逮捕嫌疑人的证据，进而促成成功的刑事审判。警探和检察官的职责是分开的，这样可以保证证据在审判之前被独立地对待。",
    "【90】\n【警方(原作向)-巡警】\n【信誉】：9-30\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：格斗（斗殴），射击，急救，一项社交技能（魅惑、话术、恐吓、说服），法律，心理学，侦查和下面的一种个人特长：汽车驾驶或骑乘。\n【介绍】：\n巡警则属于市、城镇、县治安部门或州、地区的警察机关。他们工作时可能步行、驾驶巡逻车，或者干脆坐办公室。",
    "【91】\n【私家侦探】\n【信誉】：9-30\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：技艺（摄影），乔装，法律，图书馆，一项社交技能（魅惑、话术、恐吓、说服），心理学，侦查，一项其他个人或时代特长（如计算机、锁匠、格斗、射击）。\n【介绍】：\n私家侦探通常在警察不出手的地方活跃，包括收集证据为客户准备民事诉讼，追查跑路的配偶或生意伙伴，或者代理刑事案件的私人辩护。他们和任何专业人员一样，私家侦探从不顾及自己的私人情感，只要付钱，不管是有罪还是无罪的一方的委托他们都乐得接受。私家侦探过去可能在警察队伍里工作，利用以前的业务关系为现在工作谋求优势；然而事实并非总是如此。",
    "【92】\n【教授（原作向）】\n【信誉】：20-70\n【职业属性】：教育×4\n【本职技能】：图书馆，外语，母语，心理学，任意四项其他学术、时代或个人特长。\n【介绍】：\n教授是受聘于高等院校的学者。大公司也可能聘请他们以开展学术研究与产品开发。独立的学者也靠开办业余课程作为经济来源。最重要的一点，这一职业代表了 PhD（博士）的荣誉称号，意味着可以在世界各地的大学任终身教职。教授的专长是教学和专业研究，往往在自己的专业领域内有着可圈可点的学术成就。",
    "【93】\n【淘金客】\n【信誉】：0-10\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：攀爬、急救、历史、机械维修、导航、科学（地质），侦查，任意一项其他个人或时代特长。\n【介绍】：\n淘金客一直是美国西部的特色，即便在加利福尼亚淘金热和内华达康姆斯塔克发现金银矿的日子早已经过去的现在。他们无休止地在山间漫游，寻找能使自己一夜暴富的矿脉。而且现在发现石油和发现金子一样给力。",
    "【94】\n【性工作者】\n【信誉】：5-50\n【职业属性】：教育×2＋外貌×2\n【本职技能】：技艺（任一），两项社交技能（魅惑、话术、恐吓、说服），闪避，心理学，妙手，潜行，任意一项其他个人或时代特长。\n【介绍】：\n性工作者根据场合、背景和教养，从超级值钱的应召小姐到牛郎再到站街女都有可能。往往入这一行都是权宜之计，许多人梦想有朝一日能够脱身。少数人能够自己接客，不过绝大多数人基本都是被只认钱不认人的老鸨和皮条客逼迫着工作。",
    "【95】\n【精神病学家】\n【信誉】：30-80\n【职业属性】：教育×4\n【本职技能】：外语，聆听，医学，说服，精神分析，心理学，科学（生物学，化学）。\n【介绍】：\n精神病学家是在现代专门从事精神失常诊断和治疗的医生。精神病学家掌握着精神药理学的治疗方法，使用精神类药物的资质，还能整理脑电图并对其进行计算机分析。到1930年代，任何一个医生都可以以精神病学家的身份进入美国医学协会名录中了。",
    "【96】\n【心理学家、精神分析学家】\n【信誉】：10-40\n【职业属性】：教育×4\n【本职技能】：会计，图书馆，聆听，说服，精神分析，心理学，任意两项其他学术、个人或时代特长。\n【介绍】：\n心理学家虽然也经常被叫做心理治疗师和心理咨询师，不过这些工作都只是心理学的分支。临床心理学家可能实际接触病人，并且运用各种可能的心理治疗方法。注意心理学家和专业的精神病学家的区别，后者本质上还是医生。在1920年代，对人类行为的研究还是一个新兴的领域，主要的理论还是弗洛伊德心理学。",
    "【97】\n【研究员】\n【信誉】：9-30\n【职业属性】：教育×4\n【本职技能】：历史，图书馆，一项社交技能（魅惑、话术、恐吓、说服），外语，侦查，任意三项其他学术领域。\n【介绍】：\n学术界的研究课题不计其数，尤其是在天文学、物理学和其他理论领域。私人或企业也雇用了成千上万的研究员，重点在化学、制药和工程领域。石油公司则会聘用专业的地质学家，不一而足。研究员大部分的时间都在室内工作和写作，不过有的则会经常外出考察。考察研究员通常经验丰富，思想独立又足智多谋，可能受雇于私人或者为大学进行学术研究。",
    "【98】\n【海员-军舰海员】\n【信誉】：9-30\n【职业属性】：教育×4\n【本职技能】：电工或机械维修，格斗，射击，急救，导航，驾驶（船），生存（海上），游泳。\n【介绍】：\n新入伍的海员像陆军的同行一样，开始时需要接受基本的训练。这之后他们获得军衔，并被分配到各镇守府。虽然很多海员担任像水手长副手和司炉工（管理引擎）这样的传统角色，但是也有很多经过专门训练的机械师、无线电操作员、通风管理员之类。在美国，海员通常要服四年的现役和后两年的后备役，即在国家发布动员令时有应召服役的义务。",
    "【99】\n【海员-民船海员】\n【信誉】：20-40\n【职业属性】：教育×4\n【本职技能】：急救，机械维修，自然，导航，一项社交技能（魅惑、话术、恐吓、说服），驾驶（船），侦查，游泳。\n【介绍】：\n民用船海员可能在渔船、客船，或运输原油或商品的运输船上工作。在美国，客船活跃在东西海岸和五大湖，运送渔民和游客。目前佛罗里达州在墨西哥湾和大西洋海岸拥有最多数量的客船。在禁酒令期间，许多客船船长发现把急切想喝酒的顾客运到3海里外，外国船只允许卖酒的地方是一桩赚钱的买卖。当然走私酒也报酬丰厚，但是危险就高多了。",
    "【100】\n【推销员】\n【信誉】：9-40\n【职业属性】：教育×2＋外貌×2\n【本职技能】：会计，两项社交技能（魅惑、话术、恐吓、说服），汽车驾驶，聆听，心理学，潜行或妙手，一项其他技能。\n【介绍】：\n推销员是商务工作的必需一环，他们的工作就是推广和销售公司的产品或服务。大部分推销员的时间要用来旅行、开会、和客户应酬。有些则主要坐办公室用电话联系潜在客户，还有的会在各社区巡回，挨家挨户上门推销。1920年代是企业家的年代，旅行推销成了一种日常生活方式。有些推销员在固定的地区工作，有些则可以自由漫游，寻找任何地方可能出现的商机。",
    "【101】\n【科学家】\n【信誉】：9-50\n【职业属性】：教育×4\n【本职技能】：任意三项科学专业领域，计算机或图书馆，外语，母语，一项社交技能（魅惑、话术、恐吓、说服），侦查。\n【介绍】：科学家是在追求知识的过程中挖掘真理的人。如果想要利用科学知识制造有用的物品，需要的是工程师；而如果想要扩展“可能”这个概念的范围，那就是科学家的工作了。科学家们通常在企业和大学工作，以进行他们的研究。虽然主攻一个科学领域，但是真正称职的科学家一般也能达到通晓其他数个科学领域的水平。他们对自己的母语也能使用自如，学历也相当高，甚至拥有博士学位。\n",
    "【102】\n【秘书】\n【信誉】：9-30\n【职业属性】：教育×2＋敏捷或外貌×2\n【本职技能】：会计，技艺（打字或速记），两项社交技能（魅惑、话术、恐吓、说服），母语，图书馆或计算机，心理学，任意一项其他个人或时代特长。\n【介绍】：秘书的范围是从高薪的私人管理助理到普通的打字员。这份工作的重点在于以自己各种沟通协调能力，支持主管和经理人员。因为身处企业流程的中心，许多秘书比老板对企业的内部运作和经营还要熟悉。在1920年代，秘书工作主要是通信工作，例如听写打印信件，整理文档系统，并为老板安排会议时间。有的情况下，秘书还会负责老板的生活，比如安排假期、为老板和家人置办礼物，还有保护老板的安全。\n",
    "【103】\n【店老板】\n【信誉】：20-40\n【职业属性】：教育×2＋外貌或敏捷×2\n【本职技能】：会计，两项社交技能（魅惑、话术、恐吓、说服），电气维修，聆听，机械维修，心理学，侦查。\n【介绍】：店老板经营小店、市场摊位或者是小饭馆。这种店往往都是小本自营，不过也有为其他东家照顾生意的。不少店是家族式管理，工作人员大部分都有亲属关系，其他的雇员即便有也很少。在1920年代，还有不少的老板娘开起了自己的理发店和帽店。\n",
    "【104】\n【士兵、海军陆战队士兵】\n【信誉】：9-30\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：攀爬或游泳，闪避，格斗，射击，潜行，生存，下面任选两项：急救、机械维修、外语。\n【介绍】：所有应征人员首先要在“训练营（新兵连）”接受基本训练，在训练营中新兵将学习如何行军、射击和敬礼。结束训练营的训练后，大部分的新兵会分配到步兵营，虽然也有分配到炮兵营和坦克营的。少部分会接受非战斗的训练，例如通风系统、机械装备、文职甚至军官接待。海军陆战队名义上属于海军，但是和陆军士兵在背景、训练方式和技能方面都很相近。\n",
    "【105】\n【间谍】\n【信誉】：20-60\n【职业属性】：教育×2＋外貌或敏捷×2\n【本职技能】：技艺（表演）或乔装，射击，聆听，外语，一项社交技能（魅惑、话术、恐吓、说服），心理学，妙手，潜行。\n【介绍】：间谍为国家和组织的情报部门卖命。他们能以从大使到厨房清洁工的任何职业身份作为掩饰，刺探他们所需的情报。有些间谍数年如一日的持续着卧底工作，另一些穿个马甲就换一个身份。在本国委任的间谍通常会去往外国工作。间谍除了情报收集和反情报收集的主要工作，也会被委派其他任务，例如招募新间谍和国家批准的暗杀等。\n",
    "【106】\n【学生、实习生】\n【信誉】：5-10\n【职业属性】：教育×4\n【本职技能】：语言（母语或外语），图书馆，聆听，三个学习的专业，任意两项其他个人或时代特长。\n【介绍】：学生可能在大学或学院学习，实习生则是正在接受宝贵的入职培训，获得最低报酬的公司员工。\n",
    "【107】\n【替身演员】\n【信誉】：10-50\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：攀爬，闪避，电气维修或机械维修，格斗，急救，跳跃，游泳，下面任选一项：潜水、汽车驾驶、驾驶（任一），骑乘。\n【介绍】：替身演员在电影和电视剧工业中活跃，专门模拟坠楼、车祸等灾难场景。他们通常会接受格斗技巧和舞台格斗的训练。任何的替身特技表演都是有风险的。在现代，替身演员基本都是工会的成员，想要加入工会，他们必须有证明自己能力的证书。而且，所有的特技场景还要有特技总监负责指导动作。但是在1920年代，行业规范没有成型，所以事故率和死亡率居高不下。\n",
    "【108】\n【部落成员】\n【信誉】：0-15\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：攀爬，格斗或投掷，聆听，自然，神秘学，侦查，游泳，生存（任一）。\n【介绍】：至少，从家族忠诚来说，部落文化无处不在。在部落中，亲属关系和传统习俗的首要地位是不言而喻的。一个部落通常来说是一个相对较小的群体。相比起法律和个人权利，部落更加依据个人荣耀而裁定行为。崇拜，复仇，嘉奖，以及荣耀——所有的一切都是部落成员个人所有的，而如果领袖或是仇敌被视为有荣耀的人，那么他们个人也必然在某种程度上十分有名。\n",
    "【109】\n【殡葬师】\n【信誉】：20-40\n【职业属性】：教育×4\n【本职技能】：会计，汽车驾驶，一项社交技能（魅惑、话术、恐吓、说服），历史，神秘学，心理学，科学（生物学，化学）。\n【介绍】：殡葬师又叫殡葬业者或葬礼主持人，是负责运行丧葬仪式的职业。工作也包含土葬和火化等内容。在葬礼上，殡葬师要进行防腐、裹衣、入殓、遗体美容等等工作。殡葬师的执照由各州发放。他们可能自己拥有殡仪馆，或者在别人的殡仪馆工作\n",
    "【110】\n【工会活动家】\n【信誉】：5-50\n【职业属性】：教育×4\n【本职技能】：会计，两项社交技能（魅惑、话术、恐吓、说服），格斗（斗殴），法律，聆听，操作重型机械，心理学。\n【介绍】：工会活动家是组织者、领导者，有时也是空想者或者别有用心的抗议者，通常是工人的伙伴、老板的对头。各行各业都有工会，不论是码头工人、建筑工人、矿工还是演员。在20世纪早期，工会活动家所在的工会面临着诸多危险。大企业想要毁掉它，政治家在支持它和谴责它之间摇摆不定，社会主义者和共产主义者试图影响它，还有犯罪组织试图夺取它。\n",
    "【111】\n【服务生】\n【信誉】：9-20\n【职业属性】：教育×2＋外貌或敏捷×2\n【本职技能】：会计，技艺（任一），闪避，聆听，两项社交技能（魅惑、话术、恐吓、说服），心理学，任意一项其他个人或时代特长。\n【介绍】：服务生在酒店、酒吧或者其他餐饮业场所服务顾客。通常薪酬很低，不过通过对顾客良好服务，可以得到他们给的小费。在禁酒令时期，售酒场所的服务员是非法职业。不过犯罪组织把控的地下酒吧中仍然存在许多工作机会。\n",
    "【112】\n【白领工人-职员、主管】\n【信誉】：9-20\n【职业属性】：教育×4\n【本职技能】：会计，语言，法律，图书馆或计算机，聆听，一项社交技能（魅惑、话术、恐吓、说服），任意两项其他个人或时代特长。\n【介绍】：白领工人可能是从最低等级的白领职员到中层或高层的管理人员。所属单位则可能从小型中型的本地企业直到大型的国家级甚至跨国公司。职员被扣工资是家常便饭，工作也往往单调乏味。不过如果在工作中展现出了天分，那也会被看上，将来会得到提拔。中高层管理人员的工资比较高，当然责任也比较重，要负责管理公司的日常事务。\n",
    "【113】\n【白领工人-中高层管理人员】\n【信誉】：20-80\n【职业属性】：教育×4\n【本职技能】：会计，外语，法律，两项社交技能（魅惑、话术、恐吓、说服），心理学，任意两项其他个人或时代特长。\n【介绍】：职员被扣工资是家常便饭，工作也往往单调乏味。不过如果在工作中展现出了天分，那也会被看上，将来会得到提拔。中高层管理人员的工资比较高，当然责任也比较重，要负责管理公司的日常事务。虽然未婚的白领并不少见，但很多管理人员还是很顾家，家里一般会有配偶和孩子——家庭通常是他们的期望。\n",
    "【114】\n【狂热者】\n【信誉】：0-30\n【职业属性】：教育×2＋外貌或意志×2\n【本职技能】：历史，两项社交技能（魅惑、话术、恐吓、说服），心理学，潜行，任意三项其他个人或时代特长。\n【介绍】：热情而有动力、鄙视安逸的生活，狂热者们为人类更好的生活或者为人类中最精华部分的利益而躁动不安。一些狂热者通过暴力推进他们的信仰，但是并不能说采取和平方式的就比他们好说话，他们每个人都梦想着为自己的理想辩护。\n",
    "【115】\n【饲养员】\n【信誉】：9-40\n【职业属性】：教育×4\n【本职技能】：驯兽，会计，闪避，急救，自然，医学，科学（制药，动物学）。\n【介绍】：饲养员负责动物的喂养和看护，场地管理员和服务员管理其他杂务。通常饲养员会专门照看某一种动物，可以对动物使用「医学」技能。\n",
    "【116】\n【大使】\n【信誉】：50-90\n【职业属性】：教育×2＋外貌×2\n【本职技能】：魅惑，历史，恐吓，话术，聆听，母语，说服，心理学。(用一到两种外语取代前面两种技能)",
    "【117】\n【运动员（游泳/潜水）】\n【信誉】：9-20\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：攀爬，跳跃，格斗（斗殴），外语，一项社交技能（魅惑、话术、恐吓、说服），游泳，投掷，任意一项其他个人或时代特长。",
    "【118】\n【运动员（高尔夫）】\n【信誉】：50-70\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：攀爬，跳跃，格斗（斗殴），骑术，一项社交技能（魅惑、话术、恐吓、说服），游泳，投掷，任意一项其他个人或时代特长。",
    "【119】\n【运动员（网球）】\n【信誉】：30-70\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：跳跃，格斗（斗殴），闪避，一项社交技能（魅惑、话术、恐吓、说服），心理学，侦察，投掷，任意一项其他个人或时代特长。",
    "【120】\n【运动员（田径）】\n【信誉】：9-20\n【职业属性】：教育×2＋力量或敏捷×2\n【本职技能】：攀爬，跳跃，格斗（斗殴），外语，一项社交技能（魅惑、话术、恐吓、说服），闪避，投掷，任意一项其他个人或时代特长。",
    "【121】\n【发言人】\n【信誉】：50-80\n【职业属性】：教育×4\n【本职技能】：乔装，闪避，三项社交技能（魅惑、话术、恐吓、说服），心理学，外语，任意一项其他个人或时代特长。",
    "【122】\n【保释担保人】\n【信誉】：50-80\n【职业属性】：教育×4\n【本职技能】：会计，两项社交技能（魅惑、话术、恐吓、说服），法律，图书馆，心理学，任意两项其他个人或时代特长。",
    "【123】\n【神职人员(天主教牧师)】\n【信誉】：20-70\n【职业属性】：教育×4\n【本职技能】：会计，母语，外语(拉丁文)，图书馆，神秘学，一项社交技能（魅惑、话术、恐吓、说服），心理学，任意一项其他技能。",
