                     "蜘蛛恐惧症(Arachnophobia)：对蜘蛛的恐惧。“蜘蛛网……！到处都是蜘蛛网！”你会无端地对蜘蛛产生恐惧。这种八条腿噩梦的藏身之处会令你非常不安。仅仅看见蜘蛛网都会让你冷汗直流、心跳加速。如果有蜘蛛突然碰到了你或者离你过近，你可能惊慌大叫，呼吸困难，害怕蜘蛛会杀死你。极端的时候，甚至看到蜘蛛的图片都会吓到你。附近有蜘蛛或蜘蛛存在的迹象将导致你无法抗拒的应激反应，在恐惧状态下，除了逃跑和格斗（若战斗中）以外的所有技能检定都要受到一个惩罚骰。成功使用精神分析技能可以让你暂时缓解紧张，能够在蜘蛛（或蜘蛛存在的迹象）附近停留一段时间。",
                     "闪电恐惧症(Astraphobia)：对闪电的恐惧。",
                     "废墟恐惧症(Atephobia)：对遗迹或残址的恐惧。",
                     "长笛恐惧症(Aulophobia)：对长笛的恐惧。",
                     "细菌恐惧症(Bacteriophobia)：对细菌的恐惧。",
                     "导弹/子弹恐惧症(Ballistophobia)：对导弹或子弹的恐惧。",
                     "跌落恐惧症(Basophobia)：对于跌倒或摔落的恐惧。",
                     "书籍恐惧症(Bibliophobia)：对书籍的恐惧。“把它从我眼前拿开！”你害怕书籍。强迫你拿着或阅读书籍会令你发抖、出汗、大哭。你最害怕的可能是书籍本身（发脆的纸张、皮革封面）或者它们的内容。也可能是阅读本身、学习新事物、令人恐惧的知识，让你精神崩溃。你会避免阅读，图书馆变成了你的禁区。虽然你能够进入有书架的房间（你马上就会离开！），但你一想到别人要你拿起一本书甚至去阅读，就会心跳加速，内心充满恐惧。附近有书籍将导致你无法抗拒的应激反应，在恐惧状态下，除了逃跑和格斗（若战斗中）以外的所有技能检定都要受到一个惩罚骰。成功使用精神分析技能可以让你暂时缓解紧张，能浏览书籍、阅读其中的一篇短文，或者将这本书交给他人。",
