                     "寒冷恐惧症(Cheimaphobia)：对寒冷的恐惧。",
                     "恐钟表症(Chronomentrophobia)：对于钟表的恐惧。",
                     "幽闭恐惧症(Claustrophobia)：对于处在封闭的空间中的恐惧。“求你了，我不要进到那种可怕的地窖里……”你害怕封闭空间。这可能是想象自己被关进狭小空间，逃生希望渺茫；也可能是想象自己有可能落入陷阱——也许你会窒息，或者被什么黑暗可怕的东西当作美餐？你会拒绝进入地窖、洞穴或电梯等狭小空间。如果你发现自己身处封闭空间，比如一间没有窗户的小屋或者上锁的车厢，你会开始恐慌、出汗，感觉有什么东西让你透不过气。严重的时候，你甚至会强迫性地脱衣服以求得一点虚假的自由感。身处封闭空间将导致你无法抗拒的应激反应，在恐惧状态下，除了逃跑和格斗（若战斗中）以外的所有技能检定都要受到一个惩罚骰。成功使用精神分析技能可以让你暂时缓解紧张，能穿过这一地区或者平静下来走出去。",
                     "小丑恐惧症(Coulrophobia)：对小丑的恐惧。",
                     "恐犬症(Cynophobia)：对狗的恐惧。",
                     "恶魔恐惧症(Demonophobia)：对邪灵或恶魔的恐惧。",
                     "人群恐惧症(Demophobia)：对人群的恐惧。“他们全都在看着我……”你害怕人群。你会躲避大群的人，不论这些人是在举办运动会、在热闹的大街穿行还是在教堂集会。你可能是害怕被困住，或者你觉得所有人都是你的敌人，等着你自投罗网——他们知晓你的秘密，有一点点机会就会群起而攻之。你仅仅想到自己会进入充满人的热闹场所，就会动弹不得。转过一个街角进入人群的话，你会出汗、颤抖，嘴唇发干。你身上的每一个细胞都在告诉你要逃离，如果你不逃的话，你会崩溃倒地，剧烈地抖动。身处人群中将导致你无法抗拒的应激反应，在恐惧状态下，除了逃跑和格斗（若战斗中）以外的所有技能检定都要受到一个惩罚骰。成功使用精神分析技能可以让你暂时缓解紧张，能快速穿越人群。",
                     "牙科恐惧症①(Dentophobia)：对牙医的恐惧。",
                     "丢弃恐惧症(Disposophobia)：对于丢弃物件的恐惧(贮藏癖)。",
                     "皮毛恐惧症(Doraphobia)：对动物皮毛的恐惧。",
                     "过马路恐惧症(Dromophobia)：对于过马路的恐惧。",
                     "教堂恐惧症(Ecclesiophobia)：对教堂的恐惧。",
                     "镜子恐惧症(Eisoptrophobia)：对镜子的恐惧。“不要照镜子！你的灵魂会被偷走的！”你异常害怕镜子。也许是银白的镜面里隐藏着残忍的恶魔，它知道你的秘密，唆使你去做坏事？也许是看到你在镜子里的影像会让你想起你做过的种种恐怖事件？又或者是镜子里潜藏着什么东西在等着你……镜子常常和厄运联系在一起——如果你接近镜子，你可以打破镜子并将所有厄运归到自己头上。如果你走过镜子附近，你会注意到有什么东西在看着你。你会避免携带镜子，还会尽最大努力不去看任何镜子。但如果你被强迫照了镜子，你会被纯粹的恐惧侵袭，心率增加，身体颤抖，直到你突然昏厥并倒地。附近有镜子将导致你无法抗拒的应激反应，在恐惧状态下，除了逃跑和格斗（若战斗中）以外的所有技能检定都要受到一个惩罚骰。成功使用精神分析技能可以让你暂时缓解紧张，能携带镜子或者快速向镜子里瞥一眼。",
                     "针尖恐惧症(Enetophobia)：对针或大头针的恐惧。",
