                     "恐女症(Gynophobia)：对女性的恐惧。",
                     "恐血症(Haemaphobia)：对血的恐惧。“血！到处都是血！”你害怕血。看到血会令你心跳加速、血压升高。你的嘴唇发干，头晕目眩。如果血很多（事故、搏斗或目睹手术等），你很可能恶心反胃甚至昏厥。你会对你或他人的小伤口过度反应，难以帮助别人而可能会逃跑。你会抗拒观察手术、进入灾难现场；如果可能看见血，你会拒绝进入医院。附近有血将导致你无法抗拒的应激反应，在恐惧状态下，除了逃跑和格斗（若战斗中）以外的所有技能检定都要受到一个惩罚骰。成功使用精神分析技能可以让你暂时缓解紧张，能正视血、采集带血的样本或者施行急救。",
