                     "爬虫恐惧症(Herpetophobia)：对爬行动物的恐惧。",
                     "迷雾恐惧症(Homichlophobia)：对雾的恐惧。“关上窗帘！雾里的东西会看见你的！”你异常害怕雾气和潮气。雾气是世间最凶恶歹徒的最佳掩护（想想开膛手杰克），它掩盖了一切，哪怕有人离你不过几寸远，正打算攻击你，你却无法察觉他是谁。你恐怕会永远迷失在雾里，找不到回家的路；或者什么潮湿怪异的手会无端出现，偷走你的生命。呆在充满光线的室内比出门走进迷雾要好得多。如果强迫你走出去，你会变得焦虑、气短、恶心、流汗。如果独自或强迫呆在有雾的地方一很长一段时间，你很可能会颤抖、吐字不清，甚至可能昏厥。身处雾气或潮气当中将导致你无法抗拒的应激反应，在恐惧状态下，除了逃跑和格斗（若战斗中）以外的所有技能检定都要受到一个惩罚骰。成功使用精神分析技能可以让你暂时缓解紧张，能快速通过一团雾气。",
