                     "恐水症(Hydrophobia)：对水的恐惧。“让我从这个水地狱解脱吧！”你异常害怕水。不论是海洋、河流，甚至是一浴缸的水，只是想一想沉没在这种光滑、冒泡又不断流动的液体里，都会让你充满恐惧。你会抗拒游泳，如果被突然推进水里，你会经历强烈的身体反应——颤抖、战栗、乱扑腾。你越恐慌，越可能溺水，无法游到安全地带；必须有人帮助。在极端情况下，甚至喝水都成为了令你惊恐的行为，你会出汗、心跳增加。附近有水将导致你无法抗拒的应激反应，在恐惧状态下，除了逃跑和格斗（若战斗中）以外的所有技能检定都要受到一个惩罚骰。成功使用精神分析技能可以让你暂时缓解紧张，能快速通过一片水域、洗澡等等。",
