                     "噪音恐惧症(Ligyrophobia)：对刺耳噪音的恐惧。“天！你听见那个了吗？” 你害怕巨大的声响。警报声、火警笛声、爆炸声之类急遽的巨响会让你紧张失色。其他症状还包括：换气过度、肌肉痉挛、口干舌燥、头晕目眩、心悸震颤等。你会十分小心乐器，特别是鼓；也会躲避游行、嘉年华和焰火表演。你会尽量让收音机、音乐播放器和电视的音量调到最低。看到别人吹气球会让你十分恐惧，感觉自己失去控制，你无法集中精力到噪音源以外的任何东西上。身处噪音之中将导致你无法抗拒的应激反应，在恐惧状态下，除了逃跑和格斗（若战斗中）以外的所有技能检定都要受到一个惩罚骰。注意如果你身边有枪声，惩罚仍要生效。成功使用精神分析技能可以让你暂时缓解紧张，能平静下来克服严重不良反应。",
