                     "孤独恐惧症(Monophobia)：对于一人独处的恐惧。“不要离开我！” 你极其害怕独处。如果你独处一地，周围又没有朋友，你会开始恐惧。你会因独处的想法而紧张，即使独处时间并不长。症状包括：失去斗志、极度自卑、恐慌等。你的心率会增加，吐字不清，情绪剧烈波动。只要落单，你就只能乞求陌生人的怜悯了。你可能会难以完成某些事，如穿越人群（你可能会落单）、进入电梯或者黑暗的地方、乘坐公共交通工具等。独处将导致你无法抗拒的恐惧反应，在恐惧状态下，除了逃跑和格斗（若战斗中）以外的所有技能检定都要受到一个惩罚骰。注意如果你身边有枪声，惩罚仍要生效。成功使用精神分析技能可以让你暂时缓解紧张，能平静下来克服严重不良反应。和朋友通电话也能让你缓解症状。",
