                     "魔法恐惧症(Rhabdophobia)：对魔法的恐惧。“啊啊啊！他要把我们变成蛤蟆了！” 你害怕魔术。任何和魔术有关的东西，包括卡片戏法、舞台魔术到声称拥有真正魔力的远古典籍，都可能把你变成抖成一团的废人。魔术会改变物体，也能改变你。它是神秘学，是通向黑暗邪恶世界的大门。小心魔术师。你知道他们的真相和他们造成的危险。当你身处魔术表演、魔术道具和魔术师附近时，你会紧张、极度恐惧、汗流不止、恶心、口齿不清。如果你发现自己成为了神话魔法的目标，你的反应会极其严重，会暂时产生紧张症（理智检定成功可以回避此效果）。周围有魔术时，你会产生无法抗拒的应激反应，在恐惧状态下，除了逃跑和格斗（若战斗中）以外的所有技能检定都要受到一个惩罚骰。成功使用精神分析技能可以让你暂时缓解紧张，能平静下来克服严重不良反应。",
                     "黑暗恐惧症(Scotophobia)：对黑暗或夜晚的恐惧。“灯呢？光呢？！” 你大致上极其害怕黑暗或夜晚，症状顽固。黑暗隐藏了很多东西，它们意图伤害你。如果你走进黑暗，你会被它们带走。黑暗中发生着各种各样的恶行——谋杀、偷盗、甚至更糟。你会躲避一切黑暗的地点：空房间、黑暗的地窖、茂密的森林；夜晚出门会让你产生深深的恐惧。如果你身处黑暗当中，你会呼吸困难、虚汗直冒、浑身发抖、充满恐惧。如果在黑暗中停留时间过久，你会经历强烈的焦虑发作，无法清楚地说话，更可能暂时产生紧张症（理智检定成功可以回避此效果）。身处黑暗之中将导致你产生无法抗拒的应激反应，在恐惧状态下，除了逃跑和格斗（若战斗中）以外的所有技能检定都要受到一个惩罚骰。成功使用精神分析技能可以让你暂时缓解紧张，能短时间维持自己的精神不致崩溃。",
