                     "对称恐惧症(Symmetrophobia)：对对称的恐惧。",
                     "活埋恐惧症(Taphephobia)：对于被活埋或墓地的恐惧。“到处都是死人！” 你害怕被活埋，也害怕墓地。你可能是害怕自己被宣布死亡，醒来时已经被深埋地下，无从逃脱，只能慢慢窒息。也可能是害怕坟地的死人，生者不应惊扰死者。墓地是坏地方。死者可以感受到生者，对生命产生嫉妒。有时对生命的渴求过于强烈，会让它们化作捕食生者的僵尸。附近有任何能让你联想到死亡的物品（葬礼、太平间、棺材等）将导致你产生无法抗拒的应激反应，在恐惧状态下，除了逃跑和格斗（若战斗中）以外的所有技能检定都要受到一个惩罚骰。成功使用精神分析技能可以让你暂时缓解紧张，能短时间维持自己的精神不致崩溃。",
                     "公牛恐惧症(Taurophobia)：对公牛的恐惧。",
                     "电话恐惧症(Telephonophobia)：对电话的恐惧。",
