                     "异域恐惧症(Xenophobia)：对陌生人或外国人的恐惧。“他们想抓我！” 你害怕陌生人和外国人。任何你认为不同（异）或不熟悉（怪）的人都是潜在的威胁，会让你的心脏恐惧地加快速度。陌生人不可相信，他们的动机和目标完全是不可知的。怪人隐藏着不可告人的秘密，他们可能是杀人犯，也可能是想偷走你的个人信息，好收走你的身家性命。你在面对不同于你的人时，会经历极端的情绪波动，愤怒、挑衅、纯粹的恐怖都有可能。如果你身处异国他乡或者周围全是陌生人、异族人的时候，任何环境都会让你紧张或愤怒。附近有这些人将导致你产生无法抗拒的应激反应，在恐惧状态下，除了逃跑和格斗（若战斗中）以外的所有技能检定都要受到一个惩罚骰。成功使用精神分析技能可以让你暂时缓解紧张，能短时间维持自己的精神不致崩溃。",
