                    "欣快癖(Amenomania)：不正常地感到喜悦。“我们都要被吃掉了吗？唉呀，别那么难过！凡事要往好处想！”你的症状是非理性的愉悦。不管你的身边发生了什么，你都只会感到高兴、乐观、兴高采烈。即使是面对必死无疑、极端骇人的情况，或者从外界虚空出现无法想象的怪物，你也会欺骗自己，只能看见好的一面。这种欣喜的幻觉会让你对危险视若无物，草率鲁莽，让你身边的人胆战心惊。如果有任何人或事阻止你的愉悦行为，你会极度焦虑，所有技能检定受到一个惩罚骰，直到你远离刺激为止（战斗中不生效）。你若想抵抗幻觉，看到真实的情况，必须通过困难难度的现实检定（困难理智检定）。KP 也可能根据情形或角色的状况改变某些技能检定的难度等级。成功使用精神分析技能可以让你暂时克服躁狂和它的严重不良效果。",
                    "喜花狂(Anthomania)：痴迷于花朵。",
                    "计算癖(Arithmomania)：狂热地痴迷于数字。“数字！到处都是数字！”你对数字有痴迷般的执着。你紧张时会强迫性地计数。这可能是特定的动作（掰手指），或者周围的事物（飞机、楼梯、键盘上的按键）。你可能会在阅读时强迫性地先清点出字数再开始理解文意。你也可能会记录自己到目的地到底走了多少步。你经常会觉得为了防止臆想的灾难，必须按一定的次数进行特定的步骤，比如在使用武器之前必须反复清洁它三次等等。如果有任何人或事阻止你的计数行为，你会极度焦虑，所有技能检定受到一个惩罚骰，直到躁狂缓解或你远离刺激为止（战斗中不生效）。KP 也可能根据情形或角色的状况改变某些技能检定的难度等级。成功使用精神分析技能可以让你暂时克服躁狂和它的严重不良效果。",
                    "消费癖(Asoticamania)：鲁莽冲动地消费。",
                    "隐居癖*(Automania)：过度地热爱独自隐居。(存疑，Automania实际上是恋车癖)",
                    "芭蕾癖(Balletmania)：痴迷于芭蕾舞。",
                    "窃书癖(Biliokleptomania)：无法克制偷窃书籍的冲动。",
                    "恋书狂(Bibliomania)：痴迷于书籍和/或阅读。“小书书真可爱。我全都要！”你对书籍有着病态的痴迷：表现为强迫行为，你会尽一切可能收集书籍。你可能只痴迷于一本书，也可能会收集任何书。有种冲动让你对它们产生强烈的欲望。你收集书籍的行为包括超出财力的购置行为和盗窃等。你在紧张时想要被你的书包围，狂乱地阅读或者强迫性地清点你藏书的数量。你的躁狂会影响你同世界和他人的关系。如果有任何人或事阻止你收集书籍，或者取走了你的藏书，你会极度焦虑，所有技能检定受到一个惩罚骰，直到躁狂缓解为止（战斗中不生效）。KP 也可能根据情形或角色的状况改变某些技能检定的难度等级。成功使用精神分析技能可以让你暂时克服躁狂和它的严重不良效果。",
                    "磨牙癖(Bruxomania)：无法克制磨牙的冲动。",
                    "灵臆症(Cacodemomania)：病态地坚信自己已被一个邪恶的灵体占据。",
                    "美貌狂(Callomania)：痴迷于自身的美貌。",
                    "地图狂(Cartacoethes)：在何时何处都无法控制查阅地图的冲动。",
                    "跳跃狂(Catapedamania)：痴迷于从高处跳下。",
                    "喜冷症(Cheimatomania)：对寒冷或寒冷的物体的反常喜爱。",
                    "舞蹈狂(Choreomania)：无法控制地起舞或发颤。",
                    "恋床癖(Clinomania)：过度地热爱待在床上。",
                    "恋墓狂(Coimetormania)：痴迷于墓地。",
                    "色彩狂(Coloromania)：痴迷于某种颜色。“黄色！到处都是黄色！”你对某一种颜色产生病态痴迷。你可以决定自己对它是病态喜爱还是恐惧。人们知道颜色会影响心理状态，比如绿色会使人平静，而红色会让人兴奋。这种症状会让你产生异常的想法和冲动，根据你恐惧或偏爱颜色种类的不同让你激动或平静。你会和身穿这种颜色的人时产生交流困难，也会躲避有（或没有）这种颜色的地点。当你遇到自己恐惧的颜色、或附近没有你偏爱的颜色时，你会极度焦虑，所有技能检定受到一个惩罚骰，直到你远离刺激或你（用比如全身涂满颜料等方式）满足了自己为止。KP 也可能根据情形或角色的状况改变某些技能检定的难度等级。成功使用精神分析技能可以让你暂时克服躁狂和它的严重不良效果。",
                    "小丑狂(Coulromania)：痴迷于小丑。",
                    "恐惧狂(Countermania)：执着于经历恐怖的场面。",
                    "杀戮癖(Dacnomania)：痴迷于杀戮。",
                    "魔臆症(Demonomania)：病态地坚信自己已被恶魔附身。",
                    "抓挠癖(Dermatillomania)：执着于抓挠自己的皮肤。",
                    "正义狂(Dikemania)：痴迷于目睹正义被伸张。",
                    "嗜酒狂(Dipsomania)：反常地渴求酒精。",
                    "毛皮狂(Doramania)：痴迷于拥有毛皮。(存疑)",
                    "赠物癖(Doromania)：痴迷于赠送礼物。",
                    "漂泊症(Drapetomania)：执着于逃离。",
                    "漫游癖(Ecdemiomania)：执着于四处漫游。",
                    "自恋狂(Egomania)：近乎病态地以自我为中心或自我崇拜。",
                    "职业狂(Empleomania)：对于工作的无尽病态渴求。",
                    "臆罪症(Enosimania)：病态地坚信自己带有罪孽。",
                    "学识狂(Epistemomania)：痴迷于获取学识。“我必须学到一切知识！”你会产生异常的强迫学习行为。这可能有多种表现形式：废寝忘食地阅读书籍、检查你笔记本里的统计数据、对博学的人无休止地提问等等。你如果不能学习就会十分悔恨或愤怒。你在找不到重要信息时会激越或抑郁。你会用出格的方式获取知识；偷盗、涉险，只有这样才能满足你的欲望。你在紧张时会沉迷于某些知识；你会不停重复某些词语，或者凭记忆写下潦草的笔记才能行动。如果有任何人或事阻止你依躁狂症行事，你会极度焦虑，所有技能检定受到一个惩罚骰，直到躁狂缓解或你远离刺激为止（战斗中不生效）。KP 也可能根据情形或角色的状况改变某些技能检定的难度等级。成功使用精神分析技能可以让你暂时克服躁狂和它的严重不良效果。",
                    "静止癖(Eremiomania)：执着于保持安静。",
                    "乙醚上瘾(Etheromania)：渴求乙醚。",
                    "求婚狂(Gamomania)：痴迷于进行奇特的求婚。",
                    "狂笑癖(Geliomania)：无法自制地,强迫性的大笑。",
                    "巫术狂(Goetomania)：痴迷于女巫与巫术。",
                    "写作癖(Graphomania)：痴迷于将每一件事写下来。",
                    "裸体狂(Gymnomania)：执着于裸露身体。暴露狂", "妄想狂(Habromania)：近乎病态地充满愉快的妄想(而不顾现实状况如何)。",
                    "蠕虫狂(Helminthomania)：过度地喜爱蠕虫。",
                    "枪械狂(Hoplomania)：痴迷于火器。",
                    "饮水狂(Hydromania)：反常地渴求水分。",
                    "喜鱼癖(Ichthyomania)：痴迷于鱼类。",
                    "图标狂(Iconomania)：痴迷于图标与肖像。",
                    "偶像狂(Idolomania)：痴迷于甚至愿献身于某个偶像。",
                    "信息狂(Infomania)：痴迷于积累各种信息与资讯。",
                    "射击狂(Klazomania)：反常地执着于射击。",
                    "偷窃癖(Kleptomania)：反常地执着于偷窃。“我非得到它不可。”你的症状是荒谬的强迫性盗窃行为。这种强迫症意味着你无法克制自己想要东西的冲动，偷盗东西也不为了个人使用或者获利你的强迫行为可能体现在某一类物品上，也可能体现在任何东西上；包括曲别针、笔、花、勺、铅笔甚至烟灰缸。你在偷盗之前很可能会产生紧张症状，如不安和焦虑等，偷窃之后压力就能得到释放。但是，接踵而来的是负罪感，你可能会向他人坦白自己的罪行。如果有任何人或事阻止你偷盗，你会极度焦虑，所有技能检定受到一个惩罚骰，直到躁狂缓解为止（战斗中不生效）。KP 也可能根据情形或角色的状况改变某些技能检定的难度等级。成功使用精神分析技能可以让你暂时克服躁狂和它的严重不良效果。",
                    "噪音癖(Ligyromania)：无法自制地执着于制造响亮或刺耳的噪音。“乓！” 你的症状是无法控制的制造噪音的行为，特别是在不合适的场合，如在大家都保持安静的剧院里，或者潜伏在邪教巢穴里的时候。你很可能会偏爱一两种特殊的噪音，也可能会在紧张的时候发出种种奇怪的声响。见到气球时，你会自然产生弄破它的想法。你在噪音环境下，比如用最大音量播放音乐的地方，症状可能会减轻很多。这可能来自对安静的恐惧，使你只能在吵闹的地方才能保持正常思考。如果有任何人或事阻止你制造噪音，你会极度焦虑，所有技能检定受到一个惩罚骰，直到躁狂缓解为止（战斗中不生效）。KP 也可能根据情形或角色的状况改变某些技能检定的难度等级。成功使用精神分析技能可以让你暂时克服躁狂和它的严重不良效果。",
                    "喜线癖(Linonomania)：痴迷于线绳。",
                    "彩票狂(Lotterymania)：极端地执着于购买彩票。",
                    "抑郁症(Lypemania)：近乎病态的重度抑郁倾向。",
                    "巨石狂(Megalithomania)：当站在石环中或立起的巨石旁时,就会近乎病态地写出各种奇怪的创意。",
                    "旋律狂(Melomania)：痴迷于音乐或一段特定的旋律。",
                    "作诗癖(Metromania)：无法抑制地想要不停作诗。",
                    "憎恨癖(Misomania)：憎恨一切事物,痴迷于憎恨某个事物或团体。",
                    "偏执狂(Monomania)：近乎病态地痴迷与专注某个特定的想法或创意。",
                    "夸大癖(Mythomania)：以一种近乎病态的程度说谎或夸大事物。“不是我。” 你会强迫性地说谎，或是说话时异常夸张。即便你的话会决定自己的生死，你也无法讲出真话。谎言如同铠甲，保护你不受伤害。夸大隐藏了真实的情况，助长了你的自私倾向。你用精妙的谎言把事情讲得天花乱坠，好让人觉得自己非常重要。随着你症状的加重，你的谎言越来越多。你必须记得自己说过的一切谎言，将它抄录下来帮助记忆。你越紧张，谎言和夸大就越荒诞无稽。如果你的谎言被人怀疑对质，你会极度焦虑，所有技能检定受到一个惩罚骰，直到你逃脱或者编造出让人信服的新谎言为止（战斗中不生效）。KP 也可能根据情形或角色的状况改变某些技能检定的难度等级。成功使用精神分析技能可以让你暂时克服躁狂和它的严重不良效果，可能让你暂时承认事情的真相。",
                    "臆想症(Nosomania)：妄想自己正在被某种臆想出的疾病折磨。“不净！不净！” 你产生了严重的幻觉，认为自己患上了臆想的疾病，或者健康状况极差。你可能在头脑里放大自己已有的症状，也可以臆想出一种疾病。你会证明自己的病情：一瘸一拐地走路、全身缠满绷带等等。你可能相信自己的腿已经瘸了，要让别人用轮椅推着你走；你也可能对自己进行小手术。你会纠缠医生治疗自己；如果医生不听你的话，你甚至会强迫性地盗取药物。如果别人怀疑你的身体状况，你会十分激动且不友善，所有技能检定受到一个惩罚骰，直到离开此地为止（战斗中不生效）。KP 也可能根据情形或角色的状况改变某些技能检定的难度等级。成功使用精神分析技能可以让你暂时克服躁狂和它的严重不良效果。",
                    "记录癖(Notomania)：执着于记录一切事物(例如摄影)。",
                    "恋名狂(Onomamania)：痴迷于名字(人物的､地点的､事物的)。",
                    "称名癖(Onomatomania)：无法抑制地不断重复某个词语的冲动。“F'tagn! F'tagn! F'tagn!”你无法抗拒自己反复说出某个词的欲望。这个词可能是让你精神崩溃的事件当中最有代表性的一个词。另外，这个词可能没有什么意义，甚至是胡言乱语。你也可能会强迫性地重复别人最近对你说过的话。你只有重复说这些词才能感到安心，也可能会强迫性地重复写这个词。对不理解你、或无意中说了你说的词的人，你会感到非常沮丧或恼怒。如果不能说出这个词，你会极度焦虑，所有技能检定受到一个惩罚骰，直到躁狂缓解为止（战斗中不生效）。KP 也可能根据情形或角色的状况改变某些技能检定的难度等级。成功使用精神分析技能可以让你暂时克服躁狂和它的严重不良效果。",
                    "剔指癖(Onychotillomania)：执着于剔指甲。",
                    "恋食癖(Opsomania)：对某种食物的病态热爱。",
                    "抱怨癖(Paramania)：一种在抱怨时产生的近乎病态的愉悦感。",
                    "面具狂(Personamania)：执着于佩戴面具。",
                    "幽灵狂(Phasmomania)：痴迷于幽灵。",
                    "谋杀癖(Phonomania)：病态的谋杀倾向。",
                    "渴光癖(Photomania)：对光的病态渴求。",
                    "背德癖(Planomania)：病态地渴求违背社会道德。",
                    "求财癖(Plutomania)：对财富的强迫性的渴望。",
                    "欺骗狂(Pseudomania)：无法抑制的执着于撒谎。",
                    "纵火狂(Pyromania)：执着于纵火。“烧光它！”你对火焰特别着迷，还会强迫性地点火。火焰会净化一切，而你是它的工具，净化这个黑暗的世界。你的能力是用救赎和赦免的赤红火舌，改变这个世界。你的着迷可能来源于地狱之火的信仰——火焰会将原罪焚烧成灰。或者你可能认为混沌才是万物的主宰，你放出火焰会令混沌得以自由。只要附近有火焰你就会被吸引，你盯着它燃烧的焰心，忘记时间的流逝。如果可能的话，你会随身携带生火工具。你紧张的时候会想点燃物品，如果做不到，你会极度焦虑，所有技能检定受到一个惩罚骰，直到强迫行为得到满足或你离开为止（战斗中不生效）。你可以通过一次困难难度的理智检定抑制自己的冲动。KP 也可能根据情形或角色的状况改变某些技能检定的难度等级。成功使用精神分析技能可以让你暂时克服躁狂和它的严重不良效果。",
                    "提问狂(Question-Asking Mania)：执着于提问。“这是什么？”你有强迫自己提问的冲动。不论何时何地，你都无法控制自己问问题。大多数问题都是直接对别人发问；不过有时你也会自问自答。你见到权威会发问，见到店主会发问，见到教团首脑也会发问，不一而足。你会对重要的事情特别关心，更可能对毫无疑问的显明事实一遍遍地发问。如果没有人回答出你想要的答案，你会大哭或发怒。如果有人或事阻止你提问，你会极度焦虑，所有技能检定受到一个惩罚骰，直到你满足欲望为止（战斗中不生效）。KP 也可能根据情形或角色的状况改变某些技能检定的难度等级。成功使用精神分析技能可以让你暂时克服躁狂和它的严重不良效果。",
                    "挖鼻癖(Rhinotillexomania)：执着于挖鼻子。",
                    "涂鸦癖(Scribbleomania)：沉迷于涂鸦。",
                    "列车狂(Siderodromomania)：认为火车或类似的依靠轨道交通的旅行方式充满魅力。",
                    "臆智症(Sophomania)：臆想自己拥有难以置信的智慧。",
                    "科技狂(Technomania)：痴迷于新的科技。",
                    "臆咒狂(Thanatomania)：坚信自己已被某种死亡魔法所诅咒。",
                    "臆神狂(Theomania)：坚信自己是一位神灵。",
                    "抓挠癖(Titillomaniac)：抓挠自己的强迫倾向。“该死的疹子，出去！出去！” 你的症状是病态的搔痒行为。你感觉必须反复抓挠自己的皮肤，甚至会因此受到伤害。你最可能感觉你的皮肤上有什么东西或者得了什么奇怪的病。在紧张时或你独处思考时，情绪会突然爆发。虽然全身上下的皮肤都可能成为你抓挠的目标，但最常见的目标是面部（根据 KP 裁定，长期抓搔会降低你角色的 APP）。如果有人或事阻止你搔痒，你会极度焦虑，所有技能检定受到一个惩罚骰，直到你满足欲望为止（战斗中不生效）。KP 也可能根据情形或角色的状况改变某些技能检定的难度等级。成功使用精神分析技能可以让你暂时克服躁狂和它的严重不良效果。",
