            "【DOM】爸爸/妈妈型支配者：关怀和保护，使其成为那些脆弱、敏感或需要关心的顺从者的好伴侣。养育型的支配者通常喜欢顺从者的顽皮、可爱和天真，甚至是他们的天真，并认真对待顺从者的福祉。责骂 – 当顺从者犯错时；体罚– 当他们越界时；安慰 – 拥抱你的顺从者并告诉他们他们是乖女孩或乖男孩；保护 –他们顺从者的感情；表扬 –表扬他们的伴侣听话和服从（如果你有表扬癖，这会非常好）",
