                            self.canvas_animate_icon2.bind("<Enter>", lambda event, r=role: self.draw_status_icon_canvas(event, r))
                            self.canvas_animate_icon2.bind("<Leave>", lambda event, r=role: self.destroy_status_icon_canvas(r))
                            self.frames_icon2 = [ImageTk.PhotoImage(frame.resize((50, 50), Image.LANCZOS)) for
                                                frame in
                                                ImageSequence.Iterator(image)]
                            # 显示 GIF 图片的第一帧
                            self.current_frame_icon2 = self.canvas_animate_icon2.create_image(0, 0, anchor=tk.NW,
                                                                                            image=
                                                                                            self.frames_icon2[
                                                                                                0])
                            # 播放 GIF 动画
