class MemoryMonitorApp:
    def __init__(self, root):
        self.root = root
        self.already_showed = False
        #self.ChatApp = chat_app_instance
        self.root.title("Memory Monitor")
        self.label = tk.Label(root, text=f"当前内存使用情况：")
        self.label.grid(row=0, column=0, sticky="nsew")
        self.memory_label = tk.Label(root, text="")
        self.memory_label.grid(row=1, column=0, sticky="e")
        self.warning_text = tk.Label(root, text=f"系统负荷过大！", fg="red")
        self.max_memory = self.get_total_memory()
        self.threshold_percentage = 0.8
        self.threshold = int(round(self.max_memory * self.threshold_percentage * 1024, 0)) # 设置内存使用警告的阈值，单位为MB * 1024
        self.check_interval = 1  # 检查内存使用的时间间隔，单位为秒

        self.running = True
        self.update_memory_usage()

    def get_total_memory(self):
        # 获取系统的虚拟内存信息
        virtual_memory = psutil.virtual_memory()
        # 获取总内存（以字节为单位）
        total_memory = virtual_memory.total
        # 将字节转换为GB
        total_memory_gb = total_memory / (1024 ** 3)
        return total_memory_gb

    def update_memory_usage(self):
        if self.running:
            # 获取当前进程的内存使用情况
            process = psutil.Process()
            memory_info = process.memory_info()
            memory_usage_mb = memory_info.rss / 1024 / 1024  # 将内存使用量转换为MB
            if memory_usage_mb >= 1024:
                self.memory_label.config(text=f"{memory_usage_mb/1024:.2f} GB/{self.max_memory:.2f} GB")
            else:
                self.memory_label.config(text=f"{memory_usage_mb:.2f} MB/{self.max_memory:.2f} GB")

            # 如果内存使用超过阈值，弹出警告
            if memory_usage_mb > self.threshold and self.already_showed == False:
                #self.ChatApp.quickSave()
                if self.threshold >= 1024:
                    messagebox.showwarning("内存警告", f"当前内存使用已经超过 {self.threshold/1024:.2f} GB! 请及时保存LOG！")
                else:
                    messagebox.showwarning("内存警告", f"当前内存使用已经超过 {self.threshold} MB! 请及时保存LOG！")
                self.warning_text.grid(row=2, column=0, sticky="nsew")
                self.already_showed = True
            elif self.already_showed == True:
                self.warning_text.grid(row=2, column=0, sticky="nsew")
            else:
                #self.already_showed = False
                self.warning_text.grid_forget()
            # 使用线程来定期更新内存使用情况
            threading.Timer(self.check_interval, self.update_memory_usage).start()

    def on_closing(self):
        self.running = False
        self.root.destroy()

